/* Beginner reading paths for the existing chapter, not additional course units.
   Every pair is [Chinese, English]. Each block explains its purpose BEFORE its
   equation and reads the result afterwards. Full source-based notes stay intact.
   advanced=true keeps calculation-heavy equations inside the optional details. */
"use strict";
window.OpticsGuidedLessons = {
  "1.1": {
    question: ["没有一根绳子，光究竟是什么在振动？", "Without a string, what is actually oscillating in light?"],
    setup: ["摇动绳子，移动的是波形，不是整根绳子跑到远方。光也能把变化传到远处，但不需要绳子。我们先认识描述这种变化的两种场，再问：它们遵守什么规则，规则怎样允许波传播？本节是起点，不要求你已经会向量微积分。", "On a shaken string, a pattern travels without the whole string moving away. Light also carries a changing pattern, but needs no string. First we identify two fields, then ask what rules they obey and how those rules permit waves. This is the starting point; vector calculus is not assumed for the first reading."],
    terms: [
      { name: ["场", "Field"], meaning: ["给空间中每个位置指定一个物理量；箭头同时记录大小和方向。场不是装着光的物质。", "A physical quantity assigned to each position. An arrow records both size and direction; a field is not a substance containing light."] },
      { name: ["电场 E / 磁场 B", "Electric field E / magnetic field B"], meaning: ["E 描述电荷受到的电作用；B 描述磁作用。这里的振动是这些量随时间改变。", "E describes electric action on charges; B describes magnetic action. Oscillation means these quantities change with time."] },
      { name: ["介质", "Medium"], meaning: ["光所在的材料，如空气、玻璃；材料响应会影响传播速度。真空表示没有这种物质介质。", "The material, such as air or glass, in which light travels. Its response affects wave speed. Vacuum has no material medium."] }
    ],
    observe: ["看电场与磁场变化的示意，先辨认两种箭头，不背方程。图想表达它们受共同规则约束，不是电场先走一步、再叫磁场跟上。", "Identify the electric and magnetic arrows in the coupling sketch; do not memorize equations yet. They obey joint rules, rather than E taking a turn and then telling B to follow."],
    blocks: [
      { title: ["先用四条规则描述场，而不是先背四行符号", "Start with four field rules, not four lines to memorize"], before: ["我们要描述的不只是一个点有多大的场，还包括附近的箭头怎样排列、怎样随时间变。麦克斯韦方程把这些关系分成两组：一组检查穿出小封闭面的净量，另一组检查沿小回路的环绕关系。前者叫散度，后者叫旋度；∇· 和 ∇× 分别是它们的记号。", "We need more than the field at one point: we need how nearby arrows are arranged and how they change. Maxwell's rules fall into two groups: net flow through a small closed surface, and circulation around a small loop. These are called divergence and curl, written ∇· and ∇×."], read: ["初读先留下这条主线：电荷约束电场的源，磁场没有孤立磁荷；随时间变化的电场和磁场还受到相互耦合的环绕规则约束。D、H 是把材料响应纳入描述的辅助场，下一步马上解释，不能把它们当第三、第四种光。完整公式放在下方，认识读法后再展开。", "For now, retain the thread: charges constrain electric sources; there are no isolated magnetic charges; time-changing electric and magnetic fields obey coupled circulation rules. D and H incorporate material response, not two extra kinds of light. We introduce them next; open the full equations after learning their meaning."], advanced: true },
      { title: ["同一套场规则，还需要告诉它“材料是什么”", "The field rules also need a description of the material"], before: ["刚才的规则同时含 E、B、D、H，尚不能只靠两个量算完。在线性、各向同性的简单材料里，D 与 E 同方向且成正比，B 与 H 也成正比。把两个比例系数叫介电常数 ε、磁导率 μ，材料信息就接进来了。J 是自由电流密度；σ 是导电率。", "The rules contain E, B, D and H, so two quantities alone do not close the calculation. In a simple linear isotropic material, D is proportional and parallel to E, as B is to H. Permittivity ε and permeability μ are the two proportionality constants. J is free-current density; σ is conductivity."], read: ["读 D=εE 为“材料通过 ε 把 E 与 D 联系起来”，不是二者数值相同。为了先看清波传播，接下来选均匀、不导电且无自由电荷的区域；这表示没有当地自由源，不表示场必须为零。现在可以把方程合并了。", "Read D=εE as a material relation, not numerical equality of the two fields. To isolate wave propagation, we now choose a uniform nonconducting region without free charge. No local free source does not mean zero field. We can now combine the rules."] },
      { title: ["把共同规则合起来，得到“变化能够传播”", "Combine the rules to obtain a travelling disturbance"], before: ["上一步选定均匀、无自由源且不导电的介质，ε、μ 是正的常数。两条旋度规则可消去磁场：对法拉第式再取一次旋度，用 B=μH 和 ∇×H=ε∂E/∂t 替换磁场项；无自由电荷还使 ∇·E=0。这会得到一条只含 E 的传播规则。∂ 表示只让一个变量变化、其余保持不变来求变化率，∂² 表示再求一次；∇²E 表示把 E 对 x、y、z 的空间二阶变化相加，不是 E 的平方。", "In a homogeneous, source-free, nonconducting medium, positive ε and μ are constants. Eliminate the magnetic field between the two curl rules: curl Faraday's law again, replace B by μH and use ∇×H=ε∂E/∂t. No free charge also gives ∇·E=0. This leaves a rule for E alone. ∂ differentiates with respect to one variable while the others are held fixed; ∂² repeats this. ∇²E adds the x, y and z spatial second derivatives of E, not the square of E."], eqLead: [
        ["先看消元后的结果：空间弯曲与时间弯曲要按材料系数 εμ 配平。详细的旋度运算在下方可展开。", "First read the result of elimination: spatial and temporal curvature balance through the material coefficient εμ. Expand the curl calculation below if needed."],
        ["令 1/v²=εμ，并取正的 v。它的单位是速度；下一节代入具体波形，再检验 v 是否确为波峰的传播速度。", "Set 1/v²=εμ and take positive v. It has units of speed; the next section tests a particular waveform and verifies that crests travel at v."],
        ["把 εμ 换写成 1/v²，就是这里所谓的波动方程“标准形式”；不是先前漏讲的另一条定律。", "Replacing εμ by 1/v² is what 'standard wave-equation form' means here, not a new law introduced without warning."],
        ["只看沿 z 变化的一个电场分量时，它不随 x、y 改变，这两项空间二阶导数为零，于是留下下面的一维式。", "For a field component varying only along z, its x and y derivatives vanish, leaving this one-dimensional equation."]
      ], read: ["读最后一式：沿 z 的弯曲程度，等于时间弯曲程度除以 v²。这里 v 由介质的 ε、μ 决定；式子尚未给出具体波形。需要看完整消元时，再展开下方验算；下一节会试一个随时间移动的波形。", "Read the last line as spatial curvature along z matching time curvature divided by v². The medium's ε and μ set v, but this equation does not yet specify a waveform. Expand the calculation below if desired; the next section tests a moving shape."] },
      { title: ["用玻璃式的假设材料，检查速度的意义", "Check the meaning of speed with a glass-like model"], before: ["已经知道速度来自材料，就把它与熟悉的真空速度比较。c 表示真空光速，v 表示当前介质中的相速度；折射率 n 定义为 c 与 v 的比值。下标 0 表示真空参数，下标 r 表示相对真空的比值。", "Since material determines speed, compare it with vacuum. c is vacuum light speed, v the phase speed in the medium, and refractive index n is defined as c/v. Subscript 0 denotes vacuum parameters; subscript r denotes a ratio to vacuum."], read: ["例如 εᵣ=2.25、μᵣ=1，材料使速度成为 c/√2.25=c/1.5，约 2.00×10⁸ m/s，所以 n=1.5。我们现在有了传播规则和速度；还欠一幅能随时间向前移动的波形，这就是下一节的任务。", "For εᵣ=2.25 and μᵣ=1, v=c/√2.25=c/1.5, about 2.00×10⁸ m/s, giving n=1.5. We now have a propagation rule and speed. What is still missing is an actual moving wave shape—the next section's task."] }
    ],
    check: { question: ["“无自由电荷、无自由电流”为什么不等于“没有光”？", "Why does no free charge or free current not mean no light?"], answer: ["它排除的是这片区域内的自由源，不是所有电磁场。已经进入该区域的电磁扰动仍可满足耦合规则并传播。", "It excludes local free sources, not all electromagnetic fields. A disturbance entering the region can still satisfy the coupled rules and propagate."] },
    next: ["带到 1.2.1：知道规则不等于知道波形。接下来跟着一个波峰走，看函数怎样描述它的位置。", "Into §1.2.1: knowing the rule is not yet knowing the shape. Next we follow a feature of a wave and describe its moving position."]
  },
  "1.2.1": {
    question: ["一张波形照片，怎样写成会向前移动的函数？", "How do we turn a snapshot of a wave into a moving function?"],
    setup: ["上一节告诉我们电磁扰动能够以速度 v 传播。现在不再讨论整片空间，先只看一条 z 轴：选波包上的一个凸起当记号，过一会儿它在哪里？搞清这个问题，才有必要写行波函数。", "The previous section gave a propagation speed v. Now restrict attention to a z-axis. Mark a bump on a pulse: where is it a moment later? We answer that before introducing a travelling-wave function."],
    terms: [
      { name: ["z、t", "z, t"], meaning: ["z 是沿选定直线的位置，t 是观察时刻；它们不是同一个自变量。", "z is position along the chosen line; t is observation time. They are independent variables."] },
      { name: ["波形 / 振幅", "Shape / amplitude"], meaning: ["波形是不同位置的场值怎样排列；振幅是振动能达到的最大幅度，不是传播距离。", "A shape is the arrangement of field values over position. Amplitude is the size of the oscillation, not the travel distance."] },
      { name: ["方程的解", "Solution of an equation"], meaning: ["给出一种场的时空变化，把它代回规则后每处都成立，就叫满足方程的解。", "A field pattern that satisfies the equation at every relevant position and time."] }
    ],
    observe: ["先盯住右行脉冲的最高点，播放一小段时间再暂停。它应向 +z 移动，而不是只在原地变高；再比较左行脉冲。", "Follow the peak of the right-going pulse, play briefly, then pause. It should move toward +z, not merely grow at one location. Compare the left-going pulse."],
    blocks: [
      { title: ["保持同一个凸起，位置就必须随时间增加", "Track one bump: its position must increase with time"], before: ["刚才在图中跟的是同一个波形特征，不是固定的观察点。设它起初位于 z=0，以正速度 v 右行，则 t 秒后在 z=vt。把等式移项得到 z−vt=0；同一波形上的其他点只把右边换成别的常数。于是让函数只依赖 z−vt，就能让整条形状一起平移。", "We followed the same feature, not a fixed observer. Starting at z=0 and moving right at positive speed v puts it at z=vt after time t. Rearrange to z−vt=0. Other features have other constants, so a function of z−vt shifts the whole shape together."], read: ["f 是你选定的形状，不是一种新的物理量。f(z−vt) 右行，g(z+vt) 左行；在当前线性模型里，两者可以相加。上面的波动方程是它们必须满足的检查规则，下一步挑一种余弦形状来检查。", "f names a chosen shape, not a new physical quantity. f(z−vt) moves right; g(z+vt) moves left. They may be added in this linear model. The wave equation above is the test they must pass. Next we test a particular cosine shape."] },
      { title: ["选一个周期形状，再检验它是否遵守传播规则", "Choose a periodic shape and test the propagation rule"], before: ["任意脉冲有助于看方向；持续重复的光波更适合用余弦表示。E₀ 决定最大幅度，相位 kz−ωt 告诉我们处在振动周期的哪一步；k 控制沿距离变化多快，ω 控制随时间变化多快。1.1 已把 ∇² 缩为沿 z 的二阶导数，这里先把那个一维方程摆出来，再检验余弦是否满足它。", "Pulses make direction clear; a repeating optical wave is conveniently represented by a cosine. E₀ sets its maximum size; phase kz−ωt specifies the stage in the cycle. k controls variation over distance and ω over time. Section 1.1 reduced ∇² to a second derivative along z; we first recall that equation, then test the cosine against it."], eqLead: [
        ["这是上一节得到的检查规则：空间二阶导数减去时间二阶导数的 1/v² 倍，必须为零。", "This is the test from §1.1: spatial curvature minus time curvature weighted by 1/v² must vanish."],
        ["现在提出候选波形，暂不把它当成自动成立的解。", "Now propose a candidate shape, not an automatically valid solution."],
        ["对候选式分别求两次导，得到空间项 −k²E、时间项 −ω²E；代回上一式，非零波要求 ω²=v²k²。取正的 k、ω、v 后得到：", "Two derivatives give −k²E in space and −ω²E in time. Substitution requires ω²=v²k² for a nonzero wave. For positive k, ω and v, this yields:"]
      ], read: ["所以 ω/k=v 不是另加的规定，而是候选波形通过这条方程检验的条件。完整的一阶、二阶求导及代入过程在下方；下一节把 k、ω 换成波长和周期。", "Thus ω/k=v is the condition for the candidate to pass the equation, not an extra rule. Expand the first and second derivatives and substitution below; the next section relates k and ω to wavelength and period."] },
      { title: ["把一条截面补回三维，才看懂“平面波”", "Restore the third dimension to understand a plane wave"], before: ["已经知道波沿 z 走，再问同一个 z 处的其他横向位置如何。理想模型让这些位置在同一时刻处于相同的振动阶段，连接起来就是垂直 z 轴的一张平面，叫等相位面或波面。图上看到的一条线只是这张面的截面。", "We know the wave moves along z. What about other transverse positions at the same z? In the ideal model, they share the same oscillation stage at a given time. Together they form a plane perpendicular to z: an equal-phase surface or wavefront. A line in the diagram is only its cross-section."], read: ["所以“平面”说的是波面的形状，不是光只存在于一张纸上。先会跟踪波形和辨认波面，再给重复的距离、时间各取一个名字，就自然进入波长与周期。", "Thus plane describes the wavefront, not a restriction of light to a sheet of paper. After learning to track a shape and recognize its front, we can name its repeat distance and repeat time."] }
    ],
    check: { question: ["对 f(z−vt)，为什么 t 增大时不是向 −z 走？", "Why does f(z−vt) not travel toward −z as t increases?"], answer: ["跟踪同一个特征就要保持括号不变。t 增大使 −vt 减小，z 必须增大来补偿，所以特征点向 +z 走。", "Following the same feature means keeping the argument constant. As −vt decreases, z must increase to compensate. The feature therefore travels toward +z."] },
    next: ["带到 1.2.2：我们会描述“移动”，接下来用长度和时间给这种周期性移动定量。", "Into §1.2.2: we can describe motion. Next we measure its repetition in space and time."]
  },
  "1.2.2": {
    question: ["“隔多远重复一次”和“隔多久重复一次”，是同一个问题吗？", "Is repeating after a distance the same as repeating after a time?"],
    setup: ["上一节的余弦波既在空间排成波峰波谷，也在每个固定位置随时间振动。把拍照与录像分开，就不会把图上的峰间距误当成频率。", "The cosine wave has peaks and troughs across space, while each fixed position oscillates over time. Separate a photograph from a recording so peak spacing is not mistaken for frequency."],
    terms: [
      { name: ["波长 λ", "Wavelength λ"], meaning: ["同一张空间快照上，相邻同相位置的距离，单位 m。", "Distance between adjacent equal-phase positions in a spatial snapshot, measured in m."] },
      { name: ["周期 T / 频率 ν", "Period T / frequency ν"], meaning: ["盯住一个位置，重复一次所需时间叫 T；每秒重复次数叫 ν，单位 Hz。", "At one position, T is the time for one repeat; ν is repeats per second, measured in Hz."] },
      { name: ["相位的一圈", "One phase turn"], meaning: ["一次完整振动记作 2π rad；k、ω 分别把每米、每秒的变化改用这个角度单位表示。", "A full cycle is 2π rad. k and ω express phase change per metre and per second."] }
    ],
    observe: ["分别看空间图和时间图的横轴。先指出哪一幅能量 λ，哪一幅能量 T；注意同为峰间距，横轴单位不同就代表不同的量。", "Check the horizontal axes of the spatial and temporal plots. Which measures λ, and which T? The same-looking peak spacing means different things when the axis units differ."],
    blocks: [
      { title: ["先分开两个测量，再给它们角度记号", "Separate the two measurements before naming phase rates"], before: ["空间走过一个波长、时间经过一个周期，振动都回到原阶段，也就是相位转过一圈。因此每米多少弧度叫 k=2π/λ，每秒多少弧度叫 ω=2π/T。每秒完整周期数则是 ν=1/T。它们描述同一个波，但不是同一单位。", "One wavelength in space or one period in time returns the oscillation to its starting stage: a full phase turn. Thus k=2π/λ is radians per metre, ω=2π/T radians per second, and ν=1/T complete cycles per second. They describe one wave using different units."], read: ["例如 λ 变短，k 变大，意思是同样一米内波纹更密；T 变短，ν 和 ω 变大，意思是一个点振动更快。分清这两条轴后，我们才能把距离与时间连接成速度。", "A shorter λ means larger k: more closely spaced waves over a metre. A shorter T means larger ν and ω: faster oscillation at one point. With the two axes distinguished, we can connect them through speed."] },
      { title: ["一个周期里，波峰恰好前进一个波长", "A peak advances one wavelength in one period"], before: ["把上一节追踪波峰的方法接过来：在周期 T 之后，原波峰移动到原来下一个波峰的位置，前进距离是 λ。因此速度就是 λ 除以 T；用每秒周期数 ν 代替 1/T，就变成 λν。", "Use the peak-tracking idea from the previous section: after a period T, a peak reaches the former position of the next peak, a distance λ away. Speed is therefore λ/T, or λν when repeats per second replace 1/T."], read: ["ω/k 也是同一个速度，因为分子分母里的 2π 抵消。这三种写法是在用不同计数方式描述同一次前进，不是三条互不相关的公式。", "ω/k is the same speed: the two factors of 2π cancel. These are different counting conventions for the same motion, not three unrelated formulas."] },
      { title: ["把 600 nm 变成“每秒振动多少次”", "Turn 600 nm into oscillations per second"], before: ["刚才建立了速度=波长×频率，现在给真空波长与真空速度，就能求频率。先统一单位：600 nm 是 6.00×10⁻⁷ m；再用 c 除以这个长度。", "We have speed=wavelength×frequency. Given vacuum wavelength and vacuum speed, solve for frequency. First convert 600 nm to 6.00×10⁻⁷ m, then divide c by that length."], read: ["结果是约 5.00×10¹⁴ Hz，取倒数得到周期约 2.00×10⁻¹⁵ s。这里没有新规律，只是把刚才的一次重复关系用于真实单位；k、ω 也能从同一组数据换算。", "The result is about 5.00×10¹⁴ Hz, whose reciprocal gives T≈2.00×10⁻¹⁵ s. No new law was introduced; we applied the repeat relation using physical units. The same data also determine k and ω."] },
      { title: ["速度变了，同一振动节拍对应的波距也变", "A changed speed changes the spacing at a fixed rhythm"], before: ["用刚算过的关系再问：同一束光进入另一种材料，若时间节拍保持不变，但传播变慢，相邻波峰该更近还是更远？因为每周期前进得少，它们应更近。静止、不随时间变化的界面给出这个频率不变的条件，1.6.1 会解释原因。", "Apply the same relation to light entering another material. If its time rhythm stays fixed but it travels slower, should peaks move closer or farther apart? Less advance per period means closer peaks. A stationary time-invariant interface provides the fixed-frequency condition, explained in §1.6.1."], read: ["因此频率相同不代表波长相同；必须说明波长在哪种介质中。现在我们掌握了长度与时间的计数，下一节让传播方向不再局限于 z 轴。", "Equal frequency does not mean equal wavelength; always specify the medium. With the spatial and temporal scales understood, we can next let propagation point away from the z-axis."] }
    ],
    check: { question: ["同一频率的波速度减半，波长怎样变？不要直接背式子。", "At fixed frequency, speed halves. What happens to wavelength? Explain rather than quote a formula."], answer: ["每次重复所用时间不变，每周期只走原来一半的距离，因此相邻波峰间距也减半。", "The repeat time stays fixed, but a peak travels half as far per period. The distance between adjacent peaks therefore halves."] },
    next: ["带到 1.2.3：波长告诉我们波纹多密；波矢量还会告诉我们波纹朝哪边前进。", "Into §1.2.3: wavelength tells us how dense the pattern is; a wavevector will also tell us its travel direction."]
  },
  "1.2.3": {
    question: ["光斜着走时，只写 z 方向的距离还够吗？", "If light travels obliquely, is z-distance enough?"],
    setup: ["前面一直把传播方向选作 z 轴，便于理解。现在把光转斜，不能再用任意点的 z 值代表它沿光路前进了多远。需要先把位置投影到传播方向，再用波数换成相位。", "We previously chose z along propagation. If the wave is tilted, z no longer measures how far a point lies along its travel direction. First project position onto that direction, then multiply by the wavenumber to obtain phase."],
    terms: [
      { name: ["位置矢量 r", "Position vector r"], meaning: ["从原点指向观察点的箭头；这里粗体 r 是矢量，不是球面波中的距离大小。", "An arrow from the origin to the observation point. Vector r is not the scalar distance used later for spherical waves."] },
      { name: ["波矢量 k", "Wavevector k"], meaning: ["方向指向波的传播方向，大小等于 2π/λ。", "Its direction is propagation; its magnitude is 2π/λ."] },
      { name: ["点积 k·r", "Dot product k·r"], meaning: ["先取 r 沿 k 的投影，再乘 k 的大小；结果是一个相位数值，不是箭头。", "Project r along k, then multiply by the size of k. The result is a scalar phase, not an arrow."] }
    ],
    observe: ["改变波的方向，注意波面怎样跟着转。沿波面横走保持相同振动阶段；穿过一张张波面才逐步改变相位。", "Change the propagation direction and watch the fronts rotate. Moving within a front keeps the oscillation stage unchanged; crossing fronts changes phase."],
    blocks: [
      { title: ["把“沿 z 走多远”换成“沿传播方向走多远”", "Replace z-distance by distance along propagation"], before: ["先前 kz 中的 z 恰好就是沿传播方向的距离。一般方向下用点积 k·r 完成同样的工作：位置在传播方向上越远，空间相位越大；纯横向移动则不改变它。A 是场振动的幅度与方向，不是传播方向。", "In kz, z happened to measure distance along propagation. The dot product k·r performs that job for any direction: farther along travel means larger spatial phase, while purely transverse motion leaves it unchanged. A describes the field's oscillation size and direction, not the travel direction."], read: ["取 k=(0,0,k) 时，点积就退回 kz。因此这个式子不是换了一种光，而是把已经学过的波函数写成不依赖坐标选择的形式。接下来解释它为什么仍叫平面波。", "For k=(0,0,k), the dot product reduces to kz. This is the same wave written independently of coordinate choice, not a new kind of light. Next we explain why it still has plane fronts."] },
      { title: ["同相位的点，组成垂直波矢量的平面", "Equal-phase points form a plane perpendicular to k"], before: ["固定观察时刻，要留在同一波面上，k·r 就不能改变。两点的位移若与 k 垂直，点积变化为零；所有这样的横向位移拼起来就是一张平面。垂直这张面的方向叫法向。", "At a fixed time, remaining on one front requires k·r to stay fixed. A displacement perpendicular to k changes the dot product by zero. All such transverse displacements make a plane. The perpendicular direction is its normal."], read: ["所以 k 同时给出了波面法向与传播方向。这是“波面”和“光线方向”的连接：不要把波面上横走的方向误认成向前传播的方向。", "Thus k specifies both the wavefront normal and propagation direction. This connects fronts to rays: motion within a front is not forward propagation."] },
      { title: ["做一次投影计算，检查点积究竟算了什么", "Calculate a dot product to check what it measures"], before: ["已经知道几何意义，接下来按坐标计算。点积就是同坐标的分量相乘再求和，z 分量为零时不产生贡献；波数的单位与位置的单位相乘后留下相位。", "With the geometry established, use coordinates: multiply matching components and add them. A zero z-component contributes nothing. Wavenumber times position leaves a phase."], read: ["例子给 3×2+4×1=10 rad。这个 10 是空间相位，不是场值；要知道某一时刻的场，还要减去时间相位 ωt，再放入余弦。下一节用一支转动的箭头来简化这种相位计算。", "The example gives 3×2+4×1=10 rad. That is spatial phase, not the field value. Subtract ωt and take the cosine to get the field at a particular time. Next we use a rotating arrow to simplify phase calculations."] }
    ],
    check: { question: ["在同一波面内横着移动，相位会改变吗？为什么？", "Does moving sideways within one wavefront change phase? Why?"], answer: ["同一时刻不会。位移与传播方向垂直，在该方向上的投影为零，所以空间相位不变。", "Not at a fixed time. The displacement has no projection along propagation, so spatial phase is unchanged."] },
    next: ["带到 1.2.4：我们会算相位了；接下来只是换一种更省运算的记账方式，不增加另一种真实的场。", "Into §1.2.4: we can calculate phase. Next we change the bookkeeping, not the number of physical fields."]
  },
  "1.2.4": {
    question: ["为什么讲真实的光，却要用到虚数？", "Why use imaginary numbers for real light?"],
    setup: ["前面每次都要计算一个余弦。现在想象一支等长箭头在平面内转动：箭头在横轴上的投影正好像余弦那样变化。用两个坐标保存这支箭头，既能记住幅度，也能记住相位；最后只取横向投影就回到真实场。", "So far we repeatedly evaluated cosines. Imagine a constant-length arrow rotating in a plane: its horizontal projection varies as a cosine. Two coordinates store its amplitude and phase together. Taking the horizontal projection returns the real field."],
    terms: [
      { name: ["i / 复数", "i / complex number"], meaning: ["i²=−1；a+ib 用两个数记录平面中的点，实部为 a，虚部为 b。", "i²=−1. a+ib stores a point with two coordinates; a is its real part, b its imaginary part."] },
      { name: ["相量", "Phasor"], meaning: ["用箭头长度记录幅度、用转角记录相位的计算图像，不是另一束光。", "A computational arrow storing amplitude as length and phase as angle, not another beam of light."] },
      { name: ["Re / exp(iφ)", "Re / exp(iφ)"], meaning: ["Re 表示取实部；exp(iφ)=cosφ+i sinφ 是单位转动箭头的简洁记号。", "Re means take the real part; exp(iφ)=cosφ+i sinφ compactly represents a unit rotating arrow."] }
    ],
    observe: ["调整相位，看箭头的横向投影。箭头转到一圈的四分之一时，长度没变，但投影为零；这就是为什么相位与场值不能混为一谈。", "Change phase and watch the horizontal projection. After a quarter-turn the arrow still has the same length, but its projection is zero. Phase and field value are different quantities."],
    blocks: [
      { title: ["把余弦藏进转动箭头，最后再取投影", "Store the cosine in an arrow and take its projection at the end"], before: ["刚才的图把“长度”和“转到哪里”同时存了下来。现在用复数记号写同一件事：A 乘 exp(iφ) 是长度由 A 决定、转角为 φ 的相量。光的实际场仍是它的实部，波浪号只是提醒这是复表示。", "The figure stores length and angle together. In complex notation, A times exp(iφ) is a phasor with size set by A and angle φ. The physical field remains its real part; the tilde only marks a complex representation."], read: ["这里的 φ 仍是上一节的空间相位减时间相位，并没有变成一种新的物理量。虚部帮助记账，最终实场并不是“实部和虚部的两束光相加”。", "φ is still spatial phase minus temporal phase from the previous section, not a new physical quantity. The imaginary part helps bookkeeping; the real field is not a sum of separate real and imaginary beams."] },
      { title: ["换记号的收益：复杂求导变成简单乘法", "The payoff: derivatives become simple multiplications"], before: ["如果只是算一个点，余弦已经够用。复数真正方便的地方在后续求导：同一指数因子求时间导数后，仍保留原来的形状，只多乘 −iω；空间求导同理出现 i k。这样处理线性方程比反复展开正弦余弦更省事。", "For one point, a cosine is enough. Complex notation pays off in derivatives: a time derivative preserves the exponential's shape and multiplies it by −iω; a spatial derivative gives i k. Linear equations then need less repeated sine/cosine algebra."], read: ["初读记住使用顺序：用复数做线性计算 → 需要真实场时取实部。对能量这类平方量，不能直接把复数平方当答案，1.4.3 会说明正确方法。求导细节可以按需展开。", "Retain the workflow: calculate linearly with complex quantities, then take the real part for the physical field. For squared quantities such as energy, simply squaring a complex field is not the answer; §1.4.3 explains why. The derivatives are optional below."], advanced: true },
      { title: ["用一个 60° 转角，把复数还原成场值", "Use a 60° angle to recover an actual field value"], before: ["现在检验自己是否真的会读投影。振幅取 2 V/m，相位是 π/3，也就是 60°。横向投影等于长度乘 cos60°，而 cos60°=1/2。", "Check the projection interpretation: choose amplitude 2 V/m and phase π/3, or 60°. The horizontal projection is length times cos60°, and cos60°=1/2."], read: ["实际场分量是 1 V/m，不是复数的模 2 V/m，也不是虚部 √3 V/m。幅度、相位、瞬时场值现在有了清楚分工；下一节把共同的时间转动单独拆出来。", "The actual field component is 1 V/m—not magnitude 2 V/m or imaginary coordinate √3 V/m. Amplitude, phase and instantaneous value now have distinct roles. Next we factor out the shared time rotation."] }
    ],
    check: { question: ["相量的长度一直不变，为什么真实电场仍会变？", "If phasor length stays fixed, why can the real electric field change?"], answer: ["真实场取的是横轴投影。转角变了，投影就变，即使箭头长度没有改变。", "The real field is a projection. Changing angle changes that projection even when the arrow length stays fixed."] },
    next: ["带到 1.2.5：每个位置的相量都随同一个时间节拍转动，能否只保存各处的长度和起始转角？", "Into §1.2.5: if all positions share one time rhythm, can we store only their lengths and starting angles?"]
  },
  "1.2.5": {
    question: ["每个位置都在振动，怎样只用一张“地图”记住它们？", "How can one map store oscillations at every position?"],
    setup: ["上一节用相量记录一个振动。现在同一频率的所有位置都按相同节拍转动，差别只是各处的长度和起始角。把共同的时间转动提出来，剩下的位置地图就是空间复振幅。", "A phasor records an oscillation. At a shared frequency, all positions rotate with the same time rhythm; their lengths and starting angles may differ. Factoring out time leaves a map called the spatial complex amplitude."],
    terms: [
      { name: ["A(r)", "A(r)"], meaning: ["给每个位置保存一个复数（或复矢量），包含当地振幅和参考相位。", "A complex number or vector stored at each position, containing its amplitude and reference phase."] },
      { name: ["模 / 辐角", "Magnitude / argument"], meaning: ["模是箭头长度；辐角是它的转角。复振幅不是只指长度。", "Magnitude is arrow length; argument is its angle. Complex amplitude includes both."] },
      { name: ["共同时间因子", "Common time factor"], meaning: ["exp(−iωt) 负责所有位置随时间的同频转动，负号属于本课约定。", "exp(−iωt) gives every position the shared time rotation; its minus sign is our convention."] }
    ],
    observe: ["比较两个位置的相量。移动位置时先看箭头长度，再看角度：理想无耗散平面波可以长度相同、转角不同。", "Compare phasors at two positions. Check length before angle: an ideal lossless plane wave can have equal lengths with different angles."],
    blocks: [
      { title: ["把共同的时钟拆出，留下位置地图", "Factor out the shared clock to leave a spatial map"], before: ["原来一个指数同时含位置和时间。利用指数相乘等于指数相加，把它拆成空间因子与时间因子。用 A(r) 收纳空间部分后，给定一个位置就只剩一个按时间转动的相量。", "The original exponential includes both position and time. The exponential addition rule lets us separate them into a spatial factor and a temporal factor. A(r) stores the spatial part; at a chosen position only the shared time rotation remains."], read: ["常量 A 与函数 A(r) 不能只因字母相同就当成同一个量：后者还装着位置的相位。括号里的 r 是提示“请在这个位置读取地图”。下一步用两个位置检验这张地图。", "Constant A and function A(r) are not interchangeable just because they share a letter: the latter includes spatial phase. r means read the map at this position. Next we compare two entries in that map."] },
      { title: ["走四分之一波长，是转角改变四分之一圈", "Moving a quarter-wavelength changes phase by a quarter-turn"], before: ["1.2.2 中一个波长对应 2π 的空间相位；所以沿传播方向走 λ/4，相位增加 π/2，也就是 90°。在复平面中，乘 i 正好把箭头旋转 90°，并不拉长它。", "A wavelength corresponds to a spatial phase change of 2π. Moving λ/4 along propagation therefore adds π/2, or 90°. Multiplying by i makes exactly that rotation without stretching the arrow."], read: ["所以两处复振幅可相差一个 i，但两处的振动最大幅度仍一样。要比较当时的真实场，还得给定时间并取投影，不能仅看这个 i 就说第二处场更大。", "Two complex amplitudes can differ by i while retaining the same oscillation amplitude. Comparing actual fields still needs a time and a projection; i alone does not make the second field larger."] },
      { title: ["分清“转了一点”与“真的变弱了”", "Distinguish a changed angle from genuine weakening"], before: ["刚才只是沿理想平面波的位置地图改变了相位。若箭头真的缩短，才是振幅下降；在本节均匀无耗散模型里没有这种缩短。稍后球面波会因为向外摊开而缩短，吸收材料又是另一种原因。", "The ideal plane-wave map changed phase, not size. An actually shorter arrow would mean smaller amplitude. That does not occur in this uniform lossless plane-wave model. Spherical waves later weaken by spreading; absorption is a different mechanism again."], read: ["复振幅的“复”提醒我们同时检查长度与角度。掌握这个区别，才能在后面分别讨论强度下降与相位变化，而不是把两者混在一起。", "Complex amplitude asks us to check both length and angle. That distinction will let us discuss intensity loss and phase variation separately."] }
    ],
    check: { question: ["复振幅乘 i 后，振幅一定变大了吗？", "Does multiplying a complex amplitude by i increase its amplitude?"], answer: ["没有。它转过 90°，模保持不变；真实场在某个时刻可能改变，因为投影角度变了。", "No. It rotates by 90° with unchanged magnitude. The actual field at a given time may change because its projection changes."] },
    next: ["带到 1.2.6：这些波函数描述了怎么变，接下来回到电磁规则，决定电场、磁场和传播方向怎样配合。", "Into §1.2.6: the wave functions describe variation. Next the electromagnetic rules determine how E, B and propagation fit together."]
  },
  "1.2.6": {
    question: ["光向前走，电场箭头也朝前指吗？", "If light travels forward, must its electric arrow point forward?"],
    setup: ["前面我们一直算振幅与相位，尚没有决定电场箭头朝哪里。现在用一个三维图把传播方向、电场方向和磁场方向分开；本节讨论的是均匀无源理想介质中的平面波。", "We have calculated amplitude and phase but have not yet fixed field directions. A three-dimensional picture separates propagation from E and B. This section concerns a plane wave in a uniform source-free ideal medium."],
    terms: [
      { name: ["横波", "Transverse wave"], meaning: ["振动方向垂直传播方向；“向前传播”和“向侧面振动”可以同时成立。", "Oscillation is perpendicular to propagation. Forward travel and sideways oscillation can coexist."] },
      { name: ["单位矢量 k̂", "Unit vector k̂"], meaning: ["只记传播方向，长度取 1；不同于大小为 2π/λ 的 k。", "Stores only propagation direction and has length one, unlike k with magnitude 2π/λ."] },
      { name: ["叉乘 ×", "Cross product ×"], meaning: ["从两个方向构造一个与二者垂直的方向；正向用右手规则决定。", "Builds a direction perpendicular to two given directions; its sign follows the right-hand rule."] }
    ],
    observe: ["旋转三维图，先找传播轴，再确认 E 与蓝线都在它的横向。蓝线画的是 vB，为了与 E 比长度，不是把不同单位的数值硬画成同一种长度。", "Rotate the 3D figure, locate the propagation axis, then check that E and the blue curve are transverse. Blue shows vB for length comparison with E, not raw quantities with incompatible units."],
    blocks: [
      { title: ["先从无源规则排除沿传播轴的振动", "Use the source-free rules to exclude longitudinal fields"], before: ["1.1 在均匀无源介质给出 ∇·E=0、∇·B=0。对平面波的空间指数求导，会多出沿传播方向的 k；所以两个散度为零就要求 k 与 E、B 的点积都为零。点积为零表示方向垂直，不是说场为零。因此光可以向 z 传播，而电场在 x、y 横向平面里振动。", "In the uniform source-free medium of §1.1, ∇·E=0 and ∇·B=0. Spatial differentiation of a plane-wave exponential brings down the propagation vector k. Thus zero divergence requires the dot products of k with E and B to vanish. That means perpendicular directions, not zero fields. Light can travel along z while E oscillates in the transverse x–y plane."], read: ["这一步只说明 E、B 各自都横向，还没说明它们彼此怎样摆放。下一步用另一条电磁规则把二者接起来；求导验证在下方保留。", "This establishes that E and B are each transverse, but not how they relate to each other. A second electromagnetic rule connects them next; the derivative proof remains below."], advanced: true },
      { title: ["再确定三支箭头的先后方向", "Now determine the orientation of all three arrows"], before: ["法拉第定律把 E 和 B 的变化联系起来。对我们选定的平面波，它化成一个叉乘关系：先取传播方向，再与 E 作叉乘，就得到 B 的方向。比如传播沿 +z、E 沿 +x，B 就沿 +y。", "Faraday's rule couples E and B. For this plane wave, it becomes a cross product: propagation direction crossed with E determines B. For travel along +z and E along +x, B points along +y."], read: ["这不仅让 E 与 B 互相垂直，还告诉我们它们在同一点同相翻转。空间里箭头互相垂直，不等于时间上差四分之一周期；方向夹角与相位差是不同概念。", "This makes E and B perpendicular and shows they reverse in phase at a given point. Perpendicular spatial arrows do not imply a quarter-period time delay: direction angle and phase difference are different concepts."] },
      { title: ["方向配好了，再比较两种场的幅度", "With directions fixed, compare field amplitudes"], before: ["上一步的叉乘关系还含一个 1/v，表示 B 的幅度为 E 幅度除以相速度。于是两种场不能独立任选。因为它们的单位不同，不能只说数值“谁大谁小”，要把速度和单位一起带上。", "The cross-product relation includes 1/v: B amplitude equals E amplitude divided by phase speed. The two fields cannot be independently chosen. Since their units differ, compare them through speed rather than raw numerical sizes."], read: ["真空使用 c，介质使用当地 v。能量流动则由 E×H 指示方向；在当前向前单一平面波里，它沿传播方向。下一步只用这条幅度关系算一个数。", "Use c in vacuum and local v in a medium. E×H indicates energy flow; for this single forward wave it points along propagation. Next we apply the amplitude relation numerically."] },
      { title: ["给定电场幅度，磁场不是另一个自由参数", "Given E amplitude, B is not a free parameter"], before: ["取 E₀=3 V/m。真空中用 B₀=E₀/c；若材料使 v 变成 c/2，在同一 E₀ 下就要除以一半的速度，得到两倍的 B₀。这里比较的是两种已指定的波，不是在模拟同一束光进界面。", "Take E₀=3 V/m. In vacuum, B₀=E₀/c. If a model medium has v=c/2, the same E₀ gives twice the B₀. We are comparing specified waves, not modelling transmission of one beam across an interface."], read: ["因此真空 B₀≈1.00×10⁻⁸ T，所设介质里约 2.00×10⁻⁸ T。至此平面波的形状、相位、方向与场幅度都有了联系；下一节改变的是波面形状，而不是另换一套时间振动规律。", "This gives about 1.00×10⁻⁸ T in vacuum and 2.00×10⁻⁸ T in the model medium. Shape, phase, directions and field amplitudes now connect. Next we change wavefront geometry, not the basic time-oscillation idea."] }
    ],
    check: { question: ["E 与 B 空间互相垂直，是否表示它们时间上相差 90°？", "Does spatially perpendicular E and B mean a 90° time-phase difference?"], answer: ["不表示。在这里它们同时过零、同时到极值；垂直说的是空间箭头，同相说的是时间变化。", "No. Here they cross zero and reach extrema together. Perpendicular describes spatial arrows; in phase describes time variation."] },
    next: ["带到 1.3.1：平面波把同拍的点连成平面；点源发散时，同拍的点又会连成什么形状？", "Into §1.3.1: a plane wave joins in-phase points into planes. What shape do such points make for an outward-spreading point source?"]
  },
  "1.3.1": {
    question: ["离一盏小灯越远越暗，是光被空气吃掉了吗？", "Farther from a tiny lamp, why is it dimmer even without absorption?"],
    setup: ["先做一个理想实验：把很小的光源看作一个点，周围没有吸收。前面平面波的同相位置排成平面；现在光从一点向外走，同样时间走过同样距离。我们依次解决两个不同问题：哪里振动到同一阶段？那里振动有多强？不能用一个“球面”把两者混在一起。", "Imagine an ideal point source surrounded by a nonabsorbing medium. Plane-wave equal-phase points formed planes. Now light travels outward from one point, covering equal distances in equal times. We ask two separate questions: where is the oscillation at the same stage, and how strong is it there? A spherical shape alone does not answer both."],
    terms: [
      { name: ["波面", "Wavefront"], meaning: ["同一时刻，把振动阶段相同的一层连续位置连起来所得的面；图上的圆是球面的切面，不是光只沿圆周走。", "A continuous surface at the same oscillation stage at one time. A circle in the drawing cuts a spherical surface; light is not confined to the circle."] },
      { name: ["r / A(r)", "r / A(r)"], meaning: ["r 是离点源的距离；A(r) 是该距离上的振动幅度。C 只是给幅度定标的常数，不是光速 c。", "r is distance from the point source; A(r) is the oscillation amplitude there. C is an amplitude scale, not light speed c."] },
      { name: ["功率 P / 光强 I", "Power P / intensity I"], meaning: ["P 是每秒总共送出的能量；I 是其中每平方米分到的功率。这里“光强”指辐射能流密度，单位 W/m²。", "P is total energy sent out per second. I is power per square metre, the radiative intensity in W/m² used here."] }
    ],
    observe: ["先暂停，看以 S 为中心的圆圈，想象它们是球壳的截面；再把距离比从 1 调到 2。图中幅度比降到 1/2，光强比降到 1/4。先记住这两个不同的变化，下面解释为什么。", "Pause and imagine the circles around S as cuts through spherical shells. Change distance ratio from 1 to 2. Amplitude ratio falls to 1/2 and intensity ratio to 1/4. Notice the difference; we will explain it rather than memorize it."],
    blocks: [
      { title: ["先确定形状：离源同样远，就处在同一振动阶段", "First find the shape: equal distances share an oscillation stage"], before: ["回到刚才的球壳：在均匀介质中，同一时刻发出的扰动走得同样快，所以沿不同方向走到同一距离 r 时，传播经历相同。把这一层点连接起来，就是以光源为中心的球面。“球面波”首先是在给这种同相位面的形状命名。", "In a uniform medium, a disturbance emitted at one time travels at the same speed in different directions. At the same distance r it has experienced the same travel delay. Joining that layer of points gives a sphere centred on the source. Spherical wave first names this equal-phase geometry."], read: ["这只回答“哪里同拍”，还没回答“各方向多强”。先看一个沿各方向均匀发光的标量理想模型，下一步用能量怎么摊开来确定它的幅度；实际偶极源的方向强弱会在 1.4.2 另讲。", "This answers where the rhythm matches, not how strong each direction is. We first choose an isotropic scalar idealization and determine amplitude from spreading energy next. The directional strength of an actual dipole source is addressed separately in §1.4.2."] },
      { title: ["再确定强弱：球壳越大，每平方米分到的越少", "Then find the strength: a larger shell gets less per square metre"], before: ["刚才同一层波向外走，现在在源外放两个假想球面接收能量。没有吸收时，每秒穿过两个球面的总能量相同。球面积是 4πr²，距离加倍就变成四倍；同样的总功率 P 分到四倍面积，每平方米的 I 就只剩四分之一。这里先用同种介质中 I 与振幅平方成正比的性质（1.4.3 会解释来由）：要让平方变成 1/4，振幅就只需降到 1/2。", "Place two imaginary receiving spheres outside the source. Without absorption, the same total energy per second crosses both. Their area is 4πr², so doubling distance quadruples area. The same P over four times the area gives one-quarter I. We now use intensity proportional to amplitude squared within one medium, explained in §1.4.3. To reduce its square to 1/4, amplitude must fall to 1/2."], read: ["现在才组装波函数：前面的 C/r 记录刚得到的幅度下降，后面的 cos 记录周期振动；kr 记录沿距离积累的相位，−ωt 记录随时间推进的阶段。u 是所选的标量场分量，不是能量。这样完整式子的每一部分都有来由，而不是一上来就让你背。", "Only now assemble the wave function: C/r records the amplitude reduction just derived; cos records oscillation. kr tracks spatial phase, and −ωt its time progression. u is the chosen scalar field component, not energy. Each part of the full expression now has a reason."] },
      { title: ["可选验算：这个组装出的函数真的满足传播规则吗？", "Optional check: does the assembled function obey the wave rule?"], before: ["上一步用守恒得到候选函数，现回到 1.1 的三维波动方程验算。对只依赖源距 r 的标量分量 u，空间算子 ∇²u 不再只是沿一条轴的二阶导数，而是径向二阶导数加上球壳面积增长带来的 2/r 倍一阶导数；因此不能把一维式里的 z 直接改写成 r。完整微分放在下方。", "We built a candidate from conservation; now test it against the three-dimensional wave equation of §1.1. For a scalar component u depending only on distance r, the spatial operator ∇²u becomes a radial second derivative plus (2/r) times the first derivative from spherical geometry. Simply replacing z with r in the one-dimensional equation would be wrong. The calculus is below."], eqLead: [["将上述径向空间项和原来的时间二阶项放在同一式中（仅 r>0）：", "Combine that radial spatial term with the original second time derivative (only for r>0):"]], read: ["代入候选式后，额外距离项会抵消，最后仍要求 k=ω/v。第一次学可先带着这个结论继续算距离比；若要练微积分，再展开一阶、二阶导数。", "Substitution cancels the extra distance terms and again requires k=ω/v. A first reading can continue to distance ratios; expand the first and second derivatives for a calculus check."], advanced: true },
      { title: ["用两种读数检查：距离加倍，幅度与光强分别怎样？", "Check two readings: what halves and what becomes one quarter?"], before: ["前三步已把形状、强弱和验证接起来。最后用数字检查自己有没有把场幅度与能量混淆：给定 C=6 V，在 2 m 处用 C/r 得到 3 V/m；走到 4 m 处变成 1.5 V/m。", "We have connected geometry, strength and verification. Now check that field amplitude and energy are distinct: with C=6 V, C/r gives 3 V/m at 2 m and 1.5 V/m at 4 m."], read: ["幅度减半，光强应减为原来的 1/4，而不是也减半。另用 P=1 W 单独算，2 m 与 4 m 处分别约 0.01989、0.004974 W/m²，正好验证面积规律；这两组独立给定的数据不代表同一光源。", "Halving amplitude gives one-quarter intensity, not one-half. In a separate example with P=1 W, the two intensities are about 0.01989 and 0.004974 W/m². These independently specified examples are not asserted to be one physical source."] }
    ],
    check: { question: ["不考虑吸收，离各向均匀点源两倍远，为什么光强只有四分之一，而不是一半？", "Without absorption, why is intensity one quarter at twice the distance, rather than one half?"], answer: ["同样的总功率要穿过面积变成四倍的球面，所以每平方米只分到原来的四分之一。场幅度才减半，因为光强与它的平方成正比。", "The same total power crosses a sphere with four times the area, so each square metre gets one quarter. Field amplitude halves because intensity is proportional to its square."] },
    next: ["带到 1.3.2：现在知道球壳上怎样振动；如果把接收器排成一张平面，这张平面上各处离源不一样远，又会怎样？", "Into §1.3.2: we understand oscillations on spherical shells. What if receivers instead form a plane, whose points lie at different distances from the source?"]
  },
  "1.3.2": {
    question: ["一张平屏接收球面波，中央和边缘会同时振动吗？", "Do the centre and edge of a flat screen receive a spherical wave in phase?"],
    setup: ["上一节在球壳上观察，各点离源同样远。现在把观察面换成平面，边缘的传播路程稍长。我们用已经学过的复振幅同时记住两件事：距离造成的幅度下降，以及路程造成的相位转动。", "On a shell, all points were equally distant from the source. On a flat receiver, edge paths are longer. Complex amplitude stores both consequences: amplitude reduction with distance and phase rotation with path length."],
    terms: [
      { name: ["U / u", "U / u"], meaning: ["U 是不含共同时间因子的空间复振幅；u 是最后取实部得到的真实场分量。", "U is spatial complex amplitude without the common time factor; u is the physical component recovered by taking the real part."] },
      { name: ["z₀ / ρ", "z₀ / ρ"], meaning: ["z₀ 是源到平面的垂直距离；ρ 是平面内离中央轴线的距离，不是传播总路程。", "z₀ is the axial distance from source to plane; ρ is transverse distance from its centre, not the total travel path."] },
      { name: ["路差 / 相位差", "Path difference / phase difference"], meaning: ["路差是两条路的长度差；每差一个波长，相位就多转一整圈。", "Path difference is a length difference. Each extra wavelength adds one full phase turn."] }
    ],
    observe: ["增大离轴距离，先看斜线路程，再看相量转角。幅度数值几乎不变时，相量也可能已经转了一圈；不要把屏幕看起来一样亮当成处处同相。", "Increase the off-axis distance and compare the slanted path with the phasor angle. The phasor may make a full turn while amplitude hardly changes. Similar brightness does not imply a uniform phase."],
    blocks: [
      { title: ["用复振幅，把上一节的幅度和相位分开存", "Store the previous section's amplitude and phase separately"], before: ["1.2.5 已经把同频振动写成“空间地图×共同时间转动”。球面波也能这样拆：C/r 是地图上的箭头长度，exp(ikr) 决定转角；两者一起才是 U。最后乘时间因子并取实部，就回到上一节的余弦波。", "In §1.2.5 we wrote a shared-frequency field as spatial map times common time rotation. Here C/r sets the map's arrow length and exp(ikr) its angle; together they form U. Multiplying by the time factor and taking the real part recovers the previous cosine wave."], read: ["写 U 不是把光变成另一种波，只是让每个观察点的长度与转角都能单独读取。接下来先算屏幕每一点到源的真实距离，这决定这张地图该填什么。", "U does not describe a different wave. It lets us read length and angle at each receiver independently. Next we find the actual source-to-screen distance that determines each map entry."] },
      { title: ["先用直角三角形算路程，才谈相位", "Find the path from a right triangle before finding phase"], before: ["屏幕中央距离是 z₀，离轴点与中央相差横向距离 ρ，所以斜路程 r=√(z₀²+ρ²)。多走的是 r−z₀，而不是 ρ 本身。再乘 k=2π/λ，就把米换成了相位弧度。x、y 只是把横向位置拆成两个坐标的通用写法。", "The centre path is z₀ and the transverse offset is ρ, so the slanted path is r=√(z₀²+ρ²). Its extra length is r−z₀, not ρ itself. Multiplication by k=2π/λ converts metres to phase radians. x and y simply resolve the transverse position into coordinates."], read: ["ρ 远小于 z₀ 时，可把额外路程近似为 ρ²/(2z₀)。这是小角度几何的简化；若拿去算光学相位，还要检查所丢路差相对波长是否足够小。这个几何结果马上用于下一步算例。", "For ρ much smaller than z₀, the extra path is approximately ρ²/(2z₀). That is a small-angle geometric simplification; phase calculations also require the discarded path error to be small compared with a wavelength. We now use this geometry numerically."] },
      { title: ["用 1 mm 的横移，体会光学波长有多短", "Use a 1 mm offset to appreciate the short optical wavelength"], before: ["让源离屏幕 1 m，接收点横移 1 mm。用刚才的三角形，多走的路约 0.5 μm。若波长为 500 nm，它恰好约等于一个波长，所以相位已多走一圈；这时 r 相对 1 m 却只增加很小一点。", "With a source 1 m from the screen and a 1 mm offset, the extra path is about 0.5 μm. At wavelength 500 nm, that is about one wavelength: a full extra phase turn, even though r barely differs from 1 m."], read: ["于是幅度几乎一样不代表从中央到边缘相位都一样：中间位置已经连续扫过不同阶段。进阶说明中的“共轭”就是把每个复数箭头的转角反号，在选定传播半空间后对应会聚地图；它不是本步理解路差所必需的工具。", "Nearly equal amplitudes do not imply uniform phase from centre to edge: intermediate points pass through different stages. The optional conjugation discussion reverses phasor angles and, with a selected propagation half-space, describes a converging map. It is not needed to understand path difference here."] }
    ],
    check: { question: ["两个接收点的场幅度几乎一样，能否直接断定它们相位一样？", "If two field amplitudes are nearly equal, must their phases match?"], answer: ["不能。幅度看距离的相对变化，相位看路差相对波长的大小。可见光波长很短，极小路差也可能对应显著相位差。", "No. Amplitude responds to fractional distance changes; phase responds to path difference relative to wavelength. A tiny path difference can be significant at optical wavelengths."] },
    next: ["带到 1.3.3：点源把能量摊在球壳上；如果源是一条很长的线，能量摊开的面积还会以同样速度增加吗？", "Into §1.3.3: a point source spreads over spherical shells. Does a long line source spread over an area growing at the same rate?"]
  },
  "1.3.3": {
    question: ["点状小灯和很长的发光线，远离后会一样快地变弱吗？", "Do a point source and a long luminous line weaken at the same rate?"],
    setup: ["我们不换守恒定律，只换源的几何。点源对应球壳；理想无限长、沿轴均匀的线源对应同轴圆柱。比较等长的一段圆柱侧面，就能看出距离规律为什么改变。", "Keep the conservation law but change source geometry. A point source gives shells; an ideal infinitely long uniform line gives coaxial cylinders. Comparing equal-length cylindrical side surfaces reveals why the distance law changes."],
    terms: [
      { name: ["柱面波", "Cylindrical wave"], meaning: ["同相位面像套在线源外的圆筒；r 是到线的垂直距离，不是到某个端点的距离。", "Equal-phase fronts are cylinders around the source line; r is perpendicular distance to the line, not distance to an endpoint."] },
      { name: ["pℓ", "pℓ"], meaning: ["线源每米长度向外送出的功率，单位 W/m；与点源的总功率 P 不同。", "Power emitted outward per unit source length, in W/m; different from a point source's total P."] },
      { name: ["远场近似", "Far-field approximation"], meaning: ["这里要求距离比波长尺度大得多，记为 kr≫1；离源很近不能把简式当精确解。", "Here kr≫1 means distance is large on the wavelength scale; the simple expression is not exact near the source."] }
    ],
    observe: ["把距离比从 1 增至 4，分别看柱面与球面两组读数。先比较它们的面积怎么长，再读幅度比，不要直接背两个不同的幂次。", "Increase distance ratio from 1 to 4 and compare cylindrical and spherical readings. Think about how their areas grow before reading amplitude ratios, rather than memorizing two powers."],
    blocks: [
      { title: ["球面积随 r² 长，圆柱侧面积只随 r 长", "Sphere area grows as r²; cylinder side area only as r"], before: ["取同样长的线源段 L，半径 r 的圆柱侧面积是周长 2πr 乘 L。r 加倍只让侧面积加倍，不像球面会变四倍。同一段每秒送出的功率是 pℓL，所以每平方米的光强随 1/r 下降；振幅是平方根关系，才得到 1/√r。", "For a fixed source length L, cylinder side area is circumference 2πr times L. Doubling r doubles that area, unlike the fourfold spherical increase. The segment emits pℓL, so intensity decreases as 1/r; taking the square root gives amplitude proportional to 1/√r."], read: ["波函数仍用余弦或复指数记录传播阶段，只把幅度包络改成柱面扩散的形式。符号 ≈ 提醒我们这是 kr≫1 下的简式，下一步专门解释这个限制，不另换话题。", "The wave function still uses a cosine or exponential for propagation phase; only the amplitude envelope changes with spreading geometry. The ≈ symbol marks a kr≫1 approximation. We explain that limitation next."] },
      { title: ["为什么守恒给出的简式还要检查精度？", "Why check accuracy even after using conservation?"], before: ["几何守恒只给远处衰减，不能保证猜出的复振幅在任意距离都满足波动方程。这里只看没有轴向变化的径向函数 f(r)=r⁻¹ᐟ²exp(ikr)，撇号表示对 r 求导；柱对称的空间项是一阶径向项 f′/r 加二阶项 f″。把它代入径向方程后检查剩余量，而不是照搬球面公式。", "Spreading gives far-field decay but does not make a guessed complex amplitude an exact solution everywhere. For radial f(r)=r⁻¹ᐟ²exp(ikr) without axial variation, primes mean derivatives with respect to r. The cylindrical spatial terms are f″ and f′/r. Substitution measures the remaining error; the spherical formula does not apply."], read: ["余项 f/(4r²) 与主项 k²f 相比约为 1/(4k²r²)，仅当 kr≫1 才小。汉克尔函数是严格解的名称，第一次学无需掌握它；记住线源简式有距离条件，再使用下一步的比值。", "The residual f/(4r²) is about 1/(4k²r²) relative to k²f, small only for kr≫1. A Hankel function names the exact solution; you need not master it on first reading. Keep this distance condition when using the following ratios."], advanced: true },
      { title: ["用同一个四倍距离，公平比较两种扩散", "Compare both geometries at the same fourfold distance"], before: ["在各自适用的无吸收模型里，从 r 走到 4r。柱面侧面积变四倍，所以强度变 1/4、幅度变 1/2；球面积变十六倍，所以强度变 1/16、幅度变 1/4。比较必须在同一个距离比下进行。", "Within each model's nonabsorbing regime, move from r to 4r. Cylinder area becomes fourfold, giving intensity 1/4 and amplitude 1/2. Sphere area becomes sixteenfold, giving intensity 1/16 and amplitude 1/4. Use the same distance ratio for a fair comparison."], read: ["若 pℓ=1 W/m，r=4 m 时 I=1/(8π)≈0.03979 W/m²。柱面衰减慢不是凭空多出能量，而是面积摊开得更慢；有限长的真实线源不能在任意远处永远按无限线模型算。", "For pℓ=1 W/m and r=4 m, I=1/(8π)≈0.03979 W/m². Slower weakening does not create energy; area grows more slowly. A finite real line source cannot obey the infinite-line model at arbitrarily large distances."] }
    ],
    check: { question: ["柱面波衰减比球面波慢，是否违反能量守恒？", "Does slower cylindrical decay violate energy conservation?"], answer: ["没有。守恒的是总功率；分摊面积随距离增长得不同，每单位面积剩下的功率自然不同。", "No. Total power is conserved. Different area growth gives different power per unit area."] },
    next: ["带到 1.4.1：点源、线源都是方便的模型。接下来看看真实光源有什么不同，以及何时可以用这些理想模型。", "Into §1.4.1: point and line sources are convenient models. Next we examine real sources and when those models are useful."]
  },
  "1.4.1": {
    question: ["太阳、钠灯和激光都发光，为什么不能用同一个单色波代表？", "Why not represent sunlight, a sodium lamp and a laser by one monochromatic wave?"],
    setup: ["前面用一种频率和理想几何讨论传播，现在回到“光从哪里来”。真实光源常同时含有许多频率。先看它把功率分配在哪些颜色，再决定能否在当前问题中简化成单色波。", "We used a single frequency and ideal geometries for propagation. Real sources often contain many frequencies. First inspect how their power is distributed across wavelengths, then decide whether a monochromatic approximation fits the problem."],
    terms: [
      { name: ["光谱", "Spectrum"], meaning: ["把不同波长（或频率）的成分分开，看各有多强，不是另一条空间波形。", "Shows how strong different wavelength or frequency components are, not another spatial waveform."] },
      { name: ["谱线 / 线宽", "Spectral line / linewidth"], meaning: ["谱线是集中在某一波长附近的成分；真实线通常有宽度，不是数学上无限细的一根线。", "A line is concentrated around a wavelength; a real line generally has finite width."] },
      { name: ["相干性", "Coherence"], meaning: ["比较两处或两个时刻的振动，问相位关系能否保持相关；不等于肉眼觉得颜色纯。", "How reliably oscillations at two positions or times retain a correlated phase relation; not simply perceived colour purity."] }
    ],
    observe: ["比较三种谱形的横轴。宽背景表示许多波长，几座窄峰表示几组集中成分；图只比较形状，不比较三种光源谁总功率更大。", "Compare the spectrum axes. A broad background contains many wavelengths; narrow peaks mark concentrated groups. These schematic shapes do not compare total source powers."],
    blocks: [
      { title: ["先看功率分给哪些波长，再谈光源类别", "Look at wavelength content before classifying the source"], before: ["同样“亮着”可能来自不同过程：热辐射往往覆盖宽范围；气体放电可产生原子或离子的特征线；激光通过受激辐射与反馈形成输出。这里把三类并列，是为了帮助选择模型，不是要背三个名词后就算学会。", "The same visible glow can arise from different processes: thermal radiation often spans a broad range; a discharge produces characteristic atomic or ionic lines; laser output involves stimulated emission and feedback. The comparison helps select models, not merely memorize three names."], read: ["先用图判断“连续范围还是若干峰”，再留意峰有多宽、是否多峰。实际激光也可能多模、有有限线宽，所以任何一类光源都不能只凭名字就视作绝对单色。", "First distinguish a continuous range from peaks, then ask how broad and numerous the peaks are. A laser can have multiple modes and finite linewidth; no category name alone guarantees perfect monochromaticity."] },
      { title: ["从光谱走向干涉，还欠一个稳定相位关系", "From spectra to interference, ask about phase stability"], before: ["光谱告诉我们包含哪些节拍，但能否观察到稳定干涉，还要看被比较的光场是否保持相位关联。可以把干涉先理解为两路波叠加后有时加强、有时削弱；若相对阶段迅速乱变，稳定的明暗关系就难以保留。", "A spectrum tells us which rhythms are present. Stable interference also requires correlated phases in the fields being compared. Think of interference as waves reinforcing or weakening each other; rapidly wandering relative stages make a stable pattern difficult to retain."], read: ["窄谱有助于延迟后的时间关联，但空间关联还取决于源尺寸和观察几何。于是合理的选择顺序是：看光谱 → 看本题要比较什么 → 再选单色、点源或其他近似，不是看起来一种颜色就直接套单色公式。", "A narrow spectrum supports temporal correlation, while spatial correlation also depends on source size and geometry. Choose a model by checking the spectrum, the comparison the problem needs, then the relevant approximation—not merely the apparent colour."] },
      { title: ["两条很近的黄线，仍是两种不同节拍", "Two nearby yellow lines still represent different rhythms"], before: ["用上一节的 ν=c/λ，把两条钠黄线各自换成频率后再相减。这样算出的量叫两条线中心的频差；它没有告诉我们每条线自身有多宽。先统一 nm 到 m，避免数量级出错。", "Use ν=c/λ to convert each sodium line to frequency, then subtract. The result is the difference of line centres, not either line's own width. Convert nm to m first."], read: ["589 nm 与 589.6 nm 对应约 5.18×10¹¹ Hz 的中心频差。这个例子解释“肉眼颜色接近仍非同一个频率”，而不是从双线间距直接计算光源的相干时间。接下来再问，电荷怎样辐射这些光？", "589 nm and 589.6 nm differ by about 5.18×10¹¹ Hz in centre frequency. Similar visible colours need not be identical frequencies. This separation alone does not determine coherence time. Next we ask how charges radiate."] }
    ],
    check: { question: ["看到一束很纯的黄色光，为什么还不能断言它只有一个频率？", "Why does apparently pure yellow light not guarantee a single frequency?"], answer: ["视觉分不开的近邻谱线或有限线宽仍可能存在，需要看光谱与观测条件，而不是只凭颜色。", "Nearby lines or finite linewidth may be visually unresolved. Check the spectrum and observation conditions, not colour alone."] },
    next: ["带到 1.4.2：比较光源后，挑一个最简单的经典发光模型，解释辐射方向为何可能不均匀。", "Into §1.4.2: after comparing sources, use a simple classical emitter to explain unequal radiation in different directions."]
  },
  "1.4.2": {
    question: ["一个很小的发光体，为什么不一定向各方向一样亮？", "Why need a tiny emitter not shine equally in all directions?"],
    setup: ["1.3.1 特意分开了“波面像球”和“各方向一样强”。现在用一对正负电荷的相对振动来解释这种区别：传播距离仍产生球面状相位，但振动轴会让不同观察方向得到不同强度。", "§1.3.1 separated spherical phase fronts from equal strength in every direction. Now model a pair of opposite charges oscillating relative to each other. Distance still determines spherical phase, but the oscillation axis gives different strengths in different viewing directions."],
    terms: [
      { name: ["电偶极子 / 偶极矩 p", "Electric dipole / dipole moment p"], meaning: ["一对分开的正负电荷是简单偶极子；p 用电荷量乘分离矢量记录它，不是观察处的电场。", "A separated positive/negative pair forms a simple dipole. p is charge times separation vector, not the observed electric field."] },
      { name: ["ψ", "ψ"], meaning: ["观察方向与振动轴的夹角；沿轴看是 0°，从侧面看是 90°。", "Angle between observation direction and oscillation axis: 0° along the axis, 90° from the side."] },
      { name: ["辐射远场", "Radiation far field"], meaning: ["离源足够远时主导向外输能的场；本节的轴向零点不代表源旁边全部场都为零。", "The outward energy-carrying field dominant sufficiently far away. Its axial null does not imply every near-source field vanishes."] }
    ],
    observe: ["把观察角从 90° 调到 30°，再调到 0°。看强度瓣在侧面最强、沿轴为零；图上的瓣是强弱方向图，不是光走出的弯曲轨迹。", "Change viewing angle from 90° to 30°, then 0°. Radiation is strongest sideways and zero along the axis. The lobes plot directional strength, not curved ray trajectories."],
    blocks: [
      { title: ["先定义是谁在振动，而不是把 p 当成电场", "Define the vibrating source before confusing p with a field"], before: ["要从传播回到发光，先给源一个可计算的描述。取正负电荷的分离矢量 ℓ 从负指向正，电荷量 q 乘它就是 p。若电荷中心周期性相对移动，p 就随时间振动；p₀ 表示它的振幅。", "To describe emission, first specify a calculable source. Let ℓ point from negative to positive charge; qℓ is p. Periodic relative displacement makes p oscillate in time, with amplitude p₀."], read: ["这只是给定经典源运动的模型，不是在声称真实原子就是小机械天线，也不解释量子能级。明确了振动轴，下一步才有意义去问不同方向会看到多强。", "This specifies a classical source motion; it does not make an actual atom a mechanical antenna or explain quantum energy levels. With an axis defined, directional strength becomes a meaningful question."] },
      { title: ["距离决定摊开，夹角决定往哪边辐射得强", "Distance controls spreading; angle controls radiation strength"], before: ["前面球面模型已给出场随 1/r、强度随 1/r² 的距离规律。偶极模型再增加角度因素：场幅度乘 sinψ，所以强度乘 sin²ψ。沿轴 sin0°=0，侧面 sin90°=1。完整系数还涉及源的振动频率 ω、偶极矩振幅 p₀ 和介质参数 ε、v；初读只需先理解距离与方向的两种作用。", "The spherical model supplied 1/r field and 1/r² intensity decay. A dipole adds an angular factor: field amplitude contains sinψ, so intensity contains sin²ψ. The full coefficient also involves source angular frequency ω, dipole amplitude p₀ and medium parameters ε and v; first distinguish distance from direction."], eqLead: [["进阶的第一式给出辐射远场的电场幅度 E₀，再用前节 B₀=E₀/v 得磁场幅度；只在所述理想介质、远离源时使用。", "The optional first line gives far-field electric amplitude E₀ and uses B₀=E₀/v from the earlier section. It applies to the stated ideal medium far from the source."], ["把场幅度平方，并用下一节详解的平均能流关系，才得到强度 I；因此 sinψ 变为 sin²ψ。", "Square the field amplitude and use the cycle-averaged energy-flux relation explained next section to obtain intensity I; sinψ becomes sin²ψ."]], read: ["初读先分开“距离因子”和“方向因子”，不必背完整系数。完整远场公式、场方向与能流换算放在下方；轴向零点仅针对辐射远场。", "First distinguish distance and angle without memorizing the full coefficient. The far-field expression and energy conversion are optional below; the axial null concerns radiation far from the source only."], advanced: true },
      { title: ["同一距离比两个方向，检查平方关系", "Compare two directions at one distance to test the square"], before: ["固定源、距离和频率，只改观察方向，这样不会把距离变弱混进角度效应。30° 的 sin 是 1/2，所以场幅度是侧面方向的一半；再平方才得到强度。", "Keep source, distance and frequency fixed while changing only viewing direction. This isolates angle from spreading. Since sin30°=1/2, amplitude is half the side-view value; square that to obtain intensity."], read: ["因此 30° 方向的强度是 90° 的 1/4。若同方向再把距离加倍，还要另乘距离引起的 1/4。两种原因可以分别计算，因为在当前模型中它们是独立因子。", "Intensity at 30° is one quarter of its value at 90°. Doubling distance at a fixed direction introduces another factor of one quarter. These causes can be calculated separately because they are separate factors in this model."] }
    ],
    check: { question: ["为什么“同心球面相位”不能保证“球面上处处一样亮”？", "Why do spherical phase fronts not guarantee equal brightness everywhere?"], answer: ["相位描述振动到哪一步，亮度取决于幅度平方。偶极子可有同一距离相位、不同方向幅度的 sinψ 因子。", "Phase describes oscillation stage; intensity depends on amplitude squared. A dipole can share distance-dependent phase while its amplitude varies with direction through sinψ."] },
    next: ["带到 1.4.3：我们反复用到“强度与振幅平方成正比”。接下来解释强度怎样从电磁场的能量流算出。", "Into §1.4.3: we repeatedly used intensity proportional to amplitude squared. Next we derive it from electromagnetic energy flow."]
  },
  "1.4.3": {
    question: ["电场每一瞬间都在变，光功率计到底在量什么？", "The electric field changes every instant. What does a power meter measure?"],
    setup: ["前面分别谈电场幅度和光强，但不能只因符号写在一起就把它们当同一东西。本节用“存了多少能量 → 能量怎样穿过面积 → 仪器平均读多少”的顺序，接起场与功率。", "Field amplitude and intensity have appeared side by side, but they are different quantities. Follow stored energy → energy crossing an area → averaged detector reading to connect fields to power."],
    terms: [
      { name: ["能量密度 w", "Energy density w"], meaning: ["每立方米含多少场能量，单位 J/m³，是“存量”。", "Field energy per cubic metre, in J/m³: a stored quantity."] },
      { name: ["能流密度 S / 光强 I", "Energy flux S / intensity I"], meaning: ["S 记录每秒穿过每平方米的能量和方向；I 是当前波沿传播方向能流的时间平均。", "S gives energy crossing unit area per second and its direction. I is its time average along propagation for the wave here."] },
      { name: ["E₀ / 波阻抗 Z", "E₀ / wave impedance Z"], meaning: ["E₀ 是峰值，不是仪器有效值；Z 连接电场和磁场幅度，也影响同样 E₀ 对应的能流。", "E₀ is peak amplitude, not RMS. Z relates electric and magnetic amplitudes and determines flux for a given E₀."] }
    ],
    observe: ["比较电场曲线、瞬时能流和平均线：电场有正负，向前单波的瞬时能流却不会随它一起变负。再看平均线并不在瞬时峰值上。", "Compare field, instantaneous flux and mean line. E changes sign, but a single forward wave's flux does not reverse with it. Its average also differs from its peak."],
    blocks: [
      { title: ["先把“装在空间里”与“穿过面积”分开", "Separate energy stored in space from energy crossing an area"], before: ["知道一个小体积内有能量，还不知道每秒通过门口多少。平面波以速度 v 前进，1 秒里会把长度 v 的一段能量送过截面；因此能量密度乘速度得到能流密度。电磁理论用 S=E×H 同时给出这个流量和方向。", "Stored energy in a small volume is not the rate passing through a doorway. In one second a plane wave advancing at v transports a length-v segment through a cross-section. Energy density times speed gives flux. Electromagnetism represents its size and direction by S=E×H."], read: ["w 的单位是 J/m³，S 的单位是 W/m²，二者不能互换。这里简单能量密度式还要求线性、无显著色散的材料；在这个模型中 E、B 各占一半能量，下一步把随时间变的流量平均。", "w is in J/m³; S in W/m². They are not interchangeable. The simple energy-density expression also assumes linear, nondispersive material. Electric and magnetic energies are equal here; next we average the time-dependent flow."] },
      { title: ["电场平方后再平均，才得到仪器的光强读数", "Square the field, then average to obtain intensity"], before: ["1.2.6 已把 E 与 B 关联起来，且 B=μH。把它们代入 S=E×H 后，对向前的单一平面波有 S=E²/Z；Z=√(μ/ε) 叫波阻抗，单位 Ω，表示同样的电场在该材料里对应多大能流。若 E=E₀cosφ，瞬时能流随 cos²φ 变化，一个完整周期的平均为 1/2。", "Section 1.2.6 relates E to B, with B=μH. Inserting both into S=E×H gives S=E²/Z for a single forward plane wave. Z=√(μ/ε) is wave impedance, in ohms; it tells how much flux a field produces in this material. For E=E₀cosφ, flux varies as cos²φ, whose cycle average is 1/2."], read: ["读公式为“平均光强=峰值电场平方÷两倍波阻抗”。如果给的是有效值 Eᵣₘₛ，它已包含峰值除以 √2 的平均效果，不能再多除一个 2。平方关系现在有了来源。", "Read the formula as average intensity = peak E squared divided by twice the impedance. RMS E already includes division of the peak by √2, so do not apply the factor twice. The amplitude-squared relation now has an origin."] },
      { title: ["为什么有时只写 I=A²？因为省略了比例系数", "Why sometimes write I=A²? A proportionality was absorbed"], before: ["上一步算绝对光强，需要保留 Z 和单位。若只比较同一介质里的相对强弱，可以把共同系数吸收进 A 的定义，省略写法便成 I=A²。若 A 仍明确是 V/m，A² 本身就还不是 W/m²。", "Absolute intensity needs Z and physical units. For relative comparisons in the same medium, a common coefficient can be absorbed into the definition of A, giving the shorthand I=A². If A still means V/m, its square alone is not W/m²."], read: ["使用复振幅时也要先区分“真实场平方”和“复数平方”；正确平均能流涉及复共轭，星号 * 表示把复数虚部反号。进阶式用于完整记账，初读沿用刚得到的 E₀²/(2Z) 即可。", "Also distinguish squaring a real field from squaring a complex representation. Correct phasor averaging uses the complex conjugate: * reverses the imaginary sign. The general expression is optional below; the single-wave result E₀²/(2Z) suffices here."], advanced: true },
      { title: ["把总功率、面积与电场串成一道题", "Connect total power, area and field in one calculation"], before: ["现在把 1.3.1 的面积分摊接到刚得到的场能关系：先用总辐射功率除以球面积得到 I，再倒过来由 I 求 E₀。设光源各方向均匀，光学输出 100 W，距离 10 m，无吸收。这里 100 W 不是灯泡耗电。", "Connect §1.3.1's area spreading to the field-energy relation: divide total radiated power by sphere area to get I, then invert the intensity formula to obtain E₀. Assume isotropic optical output 100 W at 10 m with no absorption—not electrical lamp consumption."], read: ["先得 I≈0.07958 W/m²，再用近似真空的 Z≈376.7 Ω 得 E₀≈7.74 V/m。这道题依次用了“功率怎样分摊”和“光强对应多大场”，说明两类知识怎样合在一起，而不是两道无关公式。", "First I≈0.07958 W/m², then near-vacuum Z≈376.7 Ω gives E₀≈7.74 V/m. The calculation joins how power spreads to what field carries that intensity; the formulas are stages of one problem."] }
    ],
    check: { question: ["同一介质里电场峰值翻倍，平均光强翻几倍？", "In the same medium, what happens to intensity if peak E doubles?"], answer: ["四倍，因为平均能流依赖峰值的平方。时间平均只带来同一个 1/2 系数，不把平方变回一次方。", "Fourfold, because mean flux depends on peak amplitude squared. Time averaging contributes the same factor 1/2, not a change of exponent."] },
    next: ["带到 1.4.4：前面的平均使用可持续重复的周期。真实光源的幅度、方向和相位若慢慢失去稳定关系，又该怎样描述？", "Into §1.4.4: our average used repeating cycles. How do we describe real sources whose amplitudes, directions and phase relations do not remain stable indefinitely?"]
  },
  "1.4.4": {
    question: ["真实光会永远按一条完美余弦振下去吗？", "Does real light oscillate as a perfect cosine forever?"],
    setup: ["前面为了学规律，暂把波写成无限持续、固定方向的单频振动。现在放松这个理想化，分别问：隔一段时间还能预测它的相位吗？长时间看有没有固定的振动方向？这是相干与偏振两个不同问题。", "To learn the rules, we used indefinitely repeating single-frequency oscillations with fixed direction. Now ask separately: how long does phase remain predictable, and is there a preferred oscillation direction over time? These are coherence and polarization, not one question."],
    terms: [
      { name: ["波列", "Wave train"], meaning: ["一段有限持续的振动图像，用来提醒理想余弦不能无限外推；并非所有真实光都按硬接缝分段。", "A finite stretch of oscillation reminding us not to extrapolate a perfect cosine forever; real light need not have sharp segment boundaries."] },
      { name: ["相干时间 τc", "Coherence time τc"], meaning: ["表征延迟后场还保持相关的时间尺度；不是每个光源共享的常数。", "A timescale for field correlation after a delay, not a universal source constant."] },
      { name: ["自然光 / 偏振", "Unpolarized light / polarization"], meaning: ["偏振描述横向振动方向的统计；理想自然光长期没有优势横向方向，不表示电场沿传播方向振动。", "Polarization describes transverse directional statistics. Ideal unpolarized light has no preferred transverse direction over time, not a longitudinal field."] }
    ],
    observe: ["比较理想载波与有限波列图，关注振幅包络和相位变化。图是解释模型，不是从真实光源采集的随机数据；不要从某一帧就判断光是否自然光。", "Compare the ideal carrier with the finite-train sketch, focusing on envelope and phase changes. This is a model, not measured random source data; one frame cannot establish whether light is unpolarized."],
    blocks: [
      { title: ["先承认余弦模型有一段有效范围", "Give the perfect-cosine model a limited useful range"], before: ["只在一小段观察时间内，相位足够可预测时，单频余弦是方便近似。跨更长延迟，真实源的相位可能逐渐失去关联；有限波列就是让我们看见这个限制，不是断言场必须突然跳断。", "A single-frequency cosine is useful over intervals where phase is sufficiently predictable. At longer delays a real source may lose phase correlation. Finite trains visualize that limitation; they do not require abrupt field jumps."], read: ["所以不是前面全部公式都错了，而是每次使用时要问观察时间与光源条件是否支持这种近似。下一步单独讨论方向，因为“相位乱”与“方向没有偏好”不能画等号。", "Earlier formulas are not simply wrong; their usefulness depends on source and observation conditions. Next we consider direction separately, since phase wandering and no directional preference are not equivalent."] },
      { title: ["相位稳定多久，与振动朝哪边，是两条轴", "Phase stability and oscillation direction are separate questions"], before: ["取垂直传播方向的两根横向轴。理想自然光长期在两轴上的平均强度相等，并没有稳定互相位；线偏振则有固定方向的振动轴。但固定方向本身并不保证它永远保持同一频率与相位。", "Choose two axes transverse to propagation. Ideal unpolarized light has equal mean intensities with no stable mutual phase relation. Linear polarization has a fixed oscillation axis, but that alone does not ensure an indefinitely fixed frequency or phase."], read: ["因此偏振片选择的是方向，不能自动把普通宽谱光变成严格单频激光。理解了“相关会维持多久”，下一步才把这个时间换成传播长度。", "A polarizer selects direction; it does not automatically turn broadband light into a perfectly single-frequency laser. Having defined how long correlation persists, we next convert that time to a propagation length."] },
      { title: ["把一段相关时间换成一段光程", "Convert a correlation time to a path-length scale"], before: ["如果光在 τc 这么长时间里保持某种相关，传播速度乘这段时间便给出相干长度的量级。谱越宽，许多不同节拍叠加后通常越快失去固定关系，因此时间尺度与谱宽的倒数量级相关；具体常数依定义而变。", "Speed times a correlation time τc gives a coherence-length scale. A broader range of rhythms generally loses a fixed relation sooner, so coherence time is of order inverse spectral width; numerical factors depend on definitions."], read: ["题设若给真空 τc=1 ns，长度估计是 3.00×10⁸×10⁻⁹=0.30 m。这是代入题设，不是所有自然光的固定长度；有色散时还需谨慎处理包络速度。", "If a problem specifies vacuum τc=1 ns, the length estimate is 3.00×10⁸×10⁻⁹=0.30 m. This applies the given value, not a universal property of unpolarized light. Dispersion also requires care with envelope velocity."] }
    ],
    check: { question: ["光通过偏振片后方向更确定，相干时间就一定很长吗？", "Does a more definite direction after a polarizer guarantee a long coherence time?"], answer: ["不一定。方向统计与延迟后的相位相关不同；选择方向本身不能保证窄谱和长时间相干。", "No. Directional statistics and delayed phase correlation differ; selecting a direction does not ensure a narrow spectrum or long coherence time."] },
    next: ["带到 1.5：已经知道自由传播与真实源的限制，接下来把光送到玻璃表面。两侧的场不能随便各写一套，需要界面规则把它们接上。", "Into §1.5: with free propagation and source limits established, bring light to a glass surface. Fields on its two sides need interface rules to connect them."]
  },
  "1.5": {
    question: ["光遇到玻璃表面，两边的电场能随意不一样吗？", "At a glass surface, can the fields on either side be unrelated?"],
    setup: ["前面把材料当成整片均匀区域。现在在两种材料间放一道界面，1.1 的电磁规则仍须成立。我们先把箭头拆成“沿表面”和“穿表面”两部分，再看哪些必须接得上；这个规则会直接用于推导反射与透射。", "We previously used a uniform material region. At an interface, the rules from §1.1 must still hold. Split each field into a part along the surface and a part through it, then identify which components must match. Reflection and transmission will follow from those rules."],
    terms: [
      { name: ["切向 / 法向", "Tangential / normal"], meaning: ["切向沿界面，法向垂直界面；本课法线从介质 1 指向介质 2。", "Tangential is along the interface; normal is perpendicular. Our normal points from medium 1 to medium 2."] },
      { name: ["连续", "Continuous"], meaning: ["从两侧无限靠近同一个界面点，指定分量趋向同一个值；不是所有向量都完全相等。", "Approaching the same interface point from each side gives the same specified component; not necessarily identical full vectors."] },
      { name: ["自由面电荷 / 面电流", "Free surface charge / current"], meaning: ["集中在界面上的自由电荷或沿面自由电流，会改变部分接续规则；不能与材料的束缚响应混淆。", "Free charge or current confined to the interface modifies some matching rules; do not confuse it with bound material response."] }
    ],
    observe: ["在图中区分穿过界面的小柱与沿界面压扁的小回路。改变介电常数比，观察法向 E 会改变，而无自由面电荷时法向 D 仍匹配。", "Distinguish the pillbox crossing the interface from the flattened loop. Change the permittivity ratio: normal E can change while normal D matches when there is no free surface charge."],
    blocks: [
      { title: ["先选分量：接得上的是哪些，不是整支箭头", "Choose components: what matches is not the whole arrow"], before: ["电场既能斜穿界面，也能沿界面。把斜箭头投影成法向与切向，才能准确说“连续”。没有自由面电荷、面电流时，规则是：B、D 的法向接得上，E、H 的切向接得上。以下两步分别说明这两组规则从哪里来。", "An oblique field has both through-surface and along-surface components. Resolve them before claiming continuity. With no free surface charge/current, normal B and D match, while tangential E and H match. The next two steps explain these two groups separately."], read: ["先用语言认清对象，完整带源向量式再按需展开。尤其 D=εE：两侧 ε 不同，即使 D 法向相等，也不要求 E 法向相等。最后的数字例子会专门检验这一点。", "Identify the components verbally before opening the full source-inclusive vector formulas. Since D=εE, unequal ε allows normal E to differ even when normal D matches. The final example tests exactly this point."], advanced: true },
      { title: ["用一个跨界小盒子，检查穿过表面的量", "Use a pillbox to compare through-surface flux"], before: ["1.1 的高斯规则统计穿过封闭面的净量。让一个小盒子横跨界面，再把厚度压到很薄：侧面面积趋零，主要只剩上下两个盖的通量。两盖的外法向相反，因此比较的是两侧法向分量之差。", "Gauss's rules count net flux through a closed surface. Place a thin box across the interface and shrink its thickness. Side area vanishes, leaving the two lids. Their outward normals oppose, so the result compares the normal components on the two sides."], read: ["没有自由面电荷时，D 从一侧穿进多少就从另一侧穿出多少；B 同样没有磁荷导致的净通量。这正是法向连续的由来。已经处理“穿过表面”，下一步再处理“沿表面走一圈”。", "Without free surface charge, the same normal D enters and leaves; B has no magnetic charge contribution either. This explains normal continuity. Having counted through-surface flux, we next count circulation along a loop."], advanced: true },
      { title: ["再用一个压扁回路，检查沿表面的场", "Use a flattened loop to compare along-surface fields"], before: ["现在不是算穿出量，而是沿一条矩形回路逐段累加场。让两条长边分别贴在两侧、短边趋零；在场及时间导数有界时，回路面积趋零，对应的磁通变化或位移电流面积项也趋零。剩下的就是两侧切向分量相比较。", "Now add fields around a rectangular loop rather than through a surface. Place its long edges on opposite sides and shrink the short edges. For bounded fields and time derivatives, flux-change and displacement-current area terms vanish with the area, leaving a comparison of tangential components."], read: ["得到 E 切向相等；H 的切向在无自由面电流时也相等。这不是凭空要求全部场一样，而是两种积分规则分别挑出了法向和切向。下一步把“D 连续但 E 不连续”算给你看。", "Tangential E matches; tangential H also matches when free surface current is absent. These are selected components derived from two integral rules, not a demand that all fields be identical. Next we calculate matching D with differing E."], advanced: true },
      { title: ["把 D=εE 代回去，接受法向 E 可以跳变", "Substitute D=εE and allow normal E to jump"], before: ["无自由面电荷给 D₁ₙ=D₂ₙ，再用每边各自的 D=εE，就成 ε₁E₁ₙ=ε₂E₂ₙ。下标 1、2 指介质，n 指法向。若第二边 ε 是四倍，为保持乘积相同，它的法向 E 就须变成四分之一。", "No free surface charge gives D₁ₙ=D₂ₙ. Using each medium's D=εE yields ε₁E₁ₙ=ε₂E₂ₙ. Subscripts 1 and 2 label media; n means normal. Four times the permittivity therefore needs one quarter of the normal E to keep the product fixed."], read: ["所以 100 V/m 变成 25 V/m；切向若给 20 V/m，则另一侧仍为 20 V/m。法向变化与切向不变并不矛盾。现在这些规则已能把界面两侧的波接起来，而不再只是一张边界公式表。", "Thus 100 V/m becomes 25 V/m; a tangential component of 20 V/m remains 20 V/m. Normal change and tangential equality are compatible. We can now use these rules to connect waves across an interface."] }
    ],
    check: { question: ["没有自由面电荷，是否就能断言两侧整个电场 E 相等？", "With no free surface charge, must the full E vector match across the interface?"], answer: ["不能。它直接约束的是 D 的法向；E 的切向也要匹配，但不同材料的 E 法向可按介电常数比改变。", "No. It constrains normal D directly. Tangential E also matches, but normal E can change with the permittivity ratio."] },
    next: ["带到 1.6.1：界面第一侧不是只有入射波，还包含反射波；总场要与第二侧透射波匹配。先问三束波能朝哪些方向走。", "Into §1.6.1: the first side contains incident plus reflected waves; their total field must match the transmitted field. First determine the allowed directions."]
  },
  "1.6.1": {
    question: ["光打到玻璃上，为什么不是朝任意方向反射、折射？", "Why does light not reflect and refract in arbitrary directions?"],
    setup: ["上一节要求界面两侧的总场接得上。在第一侧，总场包含入射光和反射光；第二侧有透射光。本节先不算分走多少能量，只解决三束光的节拍与方向。条件是界面平坦、静止、不随时间变化，材料线性。", "The previous section required the total fields to match at an interface. The first side contains incident and reflected light; the second contains transmitted light. Before calculating energy shares, we determine their rhythms and directions. We assume a flat stationary time-invariant interface and linear materials."],
    terms: [
      { name: ["入射 / 反射 / 透射", "Incident / reflected / transmitted"], meaning: ["来向界面的光、返回原介质的光、进入另一介质的光；下标 i、r、t 分别标记它们。", "Light approaching the surface, returning into its original medium, or entering the other medium. Subscripts i, r, t label them."] },
      { name: ["法线与三个角", "Normal and three angles"], meaning: ["法线垂直界面；θ₁、θᵣ、θ₂ 都从法线量起，不是从表面量起。n₁、n₂ 是两侧折射率。", "The normal is perpendicular to the surface. θ₁, θᵣ and θ₂ are measured from it, not from the surface. n₁ and n₂ are the two refractive indices."] },
      { name: ["ω / k∥", "ω / k∥"], meaning: ["ω 记录一个点随时间振动的快慢；k∥ 记录沿界面移动时相位怎样变。∥ 表示平行界面的分量。", "ω describes oscillation rate at one point; k∥ describes phase change along the interface. ∥ means the component parallel to that surface."] }
    ],
    observe: ["先找到界面、垂直它的法线和三束箭头，再把入射角从 0° 慢慢调大。比较反射角是否同样增大，以及进入较高折射率材料的光是否更靠近法线。下面解释这些变化为何受限制。", "Identify surface, normal and three arrows, then slowly increase incidence from 0°. Check equal growth of the reflected angle and bending toward the normal in higher-index material. We now explain what constrains these changes."],
    blocks: [
      { title: ["先对准两种节拍：一个点的时间、同一时刻的界面位置", "Match two rhythms: time at one point, position along the surface"], before: ["1.5 的“连续”要求界面每个位置、每个时刻的总场都能接上，不是只在某一点碰巧相等。先固定一个点看时间：单频入射驱动的非零反射、透射不能各按不同频率振动，否则刚接上的等式过一会儿就失配。再固定时刻沿界面走：三波的相位变化率也必须相同，否则在 A 点配好后，到 B 点就配不上。前者给同一个 ω，后者给同一个 k∥；振幅仍可不同。", "Continuity from §1.5 must hold at every surface position and every time, not just by coincidence once. First fix a point: nonzero waves driven by a single-frequency input cannot keep different time frequencies and still match. Then fix time and walk along the surface: phase must change at the same spatial rate, or a match at A fails at B. These requirements give a shared ω and k∥, not necessarily equal amplitudes."], read: ["所以“相位匹配”是在检查两种变化率，不是要求三束电场每一瞬间都同样大、同向。式中 k 是 1.2.3 的传播波矢量，取 ∥ 后只保留沿界面的部分。下一步利用这个共同分量，才把它换成图上的角度。", "Phase matching compares rates of variation, not equal field sizes or directions at every instant. k is the propagation wavevector from §1.2.3; ∥ selects its along-surface part. Next we convert that shared component into the diagram's angles."] },
      { title: ["再把沿界面的投影，翻译成反射角与折射角", "Convert the shared surface projection into ray angles"], before: ["1.2.2 已得到 k=ω/v；再用 1.1 的 n=c/v，即 v=c/n，代回就有 k=nω/c。接着画直角三角形：因为 θ 从法线量，沿界面那条边与斜边 k 的比是 sinθ，所以切向分量是 k sinθ。反射与入射在同一材料，k 长度相同；投影也相同，就给出两个角相等。透射到了另一材料，k 长度变了，只能改变角度来保持同一投影。", "Section 1.2.2 gave k=ω/v. Using n=c/v from §1.1, write v=c/n and substitute to get k=nω/c. In the right triangle, θ is measured from the normal, so the surface-parallel side divided by hypotenuse k is sinθ. The tangential component is therefore k sinθ. Incident and reflected waves share one medium and hence one k magnitude; matching projections gives equal angles. Transmission changes k magnitude, requiring a different angle to keep the projection fixed."], read: ["对透射把 k 换成 nω/c，再约去共同的 ω/c，就得到 n₁sinθ₁=n₂sinθ₂。这叫斯涅耳定律。它不是与上一步突然无关的新公式，而正是“沿界面必须一直配得上”的几何结果。n₂ 更大时 sinθ₂ 更小，所以折射光更靠近法线。", "For transmission substitute nω/c and cancel the shared ω/c to obtain n₁sinθ₁=n₂sinθ₂, Snell's law. It is the geometry of continued matching along the surface, not an unrelated formula. Larger n₂ requires smaller sinθ₂ and bends the ray toward the normal."] },
      { title: ["用同一束光，检查角度变与频率不变能否同时成立", "Check changed angle and unchanged frequency in one beam"], before: ["把刚得到的投影关系用于空气 n₁=1 到玻璃 n₂=1.5，入射角 30°。先求 sinθ₂=(1/1.5)×sin30°=1/3，再反查角度，得约 19.47°。反射仍在空气里，所以反射角仍是 30°。", "For air n₁=1 to glass n₂=1.5 at 30° incidence, sinθ₂=(1/1.5)sin30°=1/3, giving θ₂≈19.47°. Reflection stays in air, so its angle remains 30°."], read: ["若入射波长 600 nm，玻璃中速度变为原来 2/3，而时间节拍不变，因此波长变为 400 nm。这把 1.2.2 的速度—波长关系与本节的角度关系连上了。下一节不再问朝哪走，而问每束的场幅度有多大。", "At incident wavelength 600 nm, speed in glass becomes two thirds while frequency stays fixed, so wavelength becomes 400 nm. This connects §1.2.2's speed–wavelength relation to ray geometry. Next we ask about field sizes rather than directions."] }
    ],
    check: { question: ["为什么沿界面的 k 分量相同，却不要求整个 k 相同？", "Why must the surface component of k match, but not all of k?"], answer: ["边界在同一表面比较场，所以限制沿面相位变化。进入另一材料后速度与波长可变，k 的总长度与法向分量因此可以不同。", "The boundary compares fields on the same surface and constrains phase variation along it. Another material can change speed and wavelength, allowing a different total k and normal component."] },
    next: ["带到 1.6.2：方向已确定，剩下用切向 E、H 的接续规则，解出反射和透射的幅度。", "Into §1.6.2: with directions determined, use tangential E and H matching to find reflected and transmitted amplitudes."]
  },
  "1.6.2": {
    question: ["玻璃既反光又透光，两个场幅度分别占多少？", "Glass both reflects and transmits. How large are the two fields?"],
    setup: ["上一节已找出三束光的方向，现在求它们的幅度关系。电场可能有不同横向方向，投影到界面时几何关系不同，所以先把它拆成 s、p 两个独立通道，再分别接上 E、H。两侧取无吸收、非磁性的理想材料。", "The directions are known; now find field sizes. Different transverse electric orientations project differently onto the surface, so split them into independent s and p channels before matching E and H. Both materials are ideal, nonabsorbing and nonmagnetic."],
    terms: [
      { name: ["入射面 / s、p", "Incidence plane / s, p"], meaning: ["入射光线与法线组成入射面。s 电场垂直这个面，p 电场在这个面内；二者都垂直各自传播方向。", "The incident ray and normal define a plane. s electric field is perpendicular to that plane; p lies in it. Both remain perpendicular to their own propagation direction."] },
      { name: ["小写 r、t", "Lowercase r, t"], meaning: ["分别是反射场、透射场与入射场的带方向振幅之比，不是能量百分数。下标 s、p 区分通道。", "Ratios of signed reflected or transmitted field amplitude to incident amplitude, not energy fractions. s and p label channels."] },
      { name: ["正向基底", "Positive basis direction"], meaning: ["先规定箭头哪边算正，再说系数正负。这里每束波取 p̂=ŝ×k̂；反射波的 p 正向会随传播方向改变。", "Choose what counts as a positive arrow before interpreting signs. We use p̂=ŝ×k̂ for each wave; reflected p changes with its propagation direction."] }
    ],
    observe: ["先只跟踪 rₛ、tₛ 两条曲线，再看 p 通道。若见负值，不要理解成负能量；本图画的是场系数。能量占比会在 1.6.4 另算。", "First follow the rₛ and tₛ curves, then the p channel. Negative values are signed fields, not negative energy. Energy fractions follow in §1.6.4."],
    blocks: [
      { title: ["先规定两种振动方向与系数，不急着背长分式", "Define orientations and ratios before memorizing fractions"], before: ["上一节的角度只确定光往哪走，还不能确定 E 朝哪振。s、p 是把横向电场拆成两条互相垂直的轴；任意横向振动都可以在这两轴上分解。每条轴各有一个反射比 r 和透射比 t。下面的大分式是两组边界方程解出的结果，不是本节学习的起点。", "Ray angles determine travel, not electric oscillation direction. s and p form two perpendicular transverse axes, allowing any transverse field to be resolved into them. Each channel has r and t. The long fractions below are results of two boundary equations, not the starting point."], read: ["先保留“拆方向 → 各列两条接续式 → 解幅度比”的路线。尤其 p 的正向跟着各束传播方向变；因此不同通道的正负不能脱离箭头约定直接比较。接下来先解容易画清楚的 s，再解 p；完整反射分式会在各自的两条接续式之后出现。", "Keep the route: split orientations → write two matching equations per channel → solve amplitude ratios. p's positive direction follows each ray, so signs across channels require their bases. First solve the simpler s geometry, then p. Each full reflection coefficient will appear after the two matching equations that produce it."] },
      { title: ["s 通道：把入射幅度当 1，解两条接续式", "s channel: set incident amplitude to 1 and solve two conditions"], before: ["按非零入射场幅度归一化，入射写 1，反射写 rₛ，透射写 tₛ。s 的 E 都沿同一界面方向，切向 E 连续给第一式；反射方向翻转使 H 的切向符号相反，得到第二式中的 1−rₛ。非磁性介质 H/E 与 n 成正比，沿界面投影带 cosθ。", "Divide by nonzero incident amplitude: incident is 1, reflected rₛ, transmitted tₛ. All s electric fields share one surface direction, giving the first condition. Reversed propagation flips tangential H, giving 1−rₛ in the second. For nonmagnetic media H/E is proportional to n, and the surface projection brings cosθ."], eqLead: [
        ["先写切向电场相等：入射加反射，等于透射。", "First match tangential E: incident plus reflected equals transmitted."],
        ["再写切向磁场相等：反射方向翻转；两侧的 n、角度可以不同。", "Then match tangential H: reflection reverses its sign; indices and angles may differ."],
        ["将 tₛ=1+rₛ 代入第二式，展开并把 rₛ 收到同侧，得到反射场比。", "Substitute tₛ=1+rₛ into the second equation, expand, and collect rₛ on one side to obtain the reflected-field ratio."],
        ["最后把 rₛ 代回第一式，才得到透射场比。详细移项在下方。", "Finally substitute rₛ back into the first equation for the transmitted-field ratio. The detailed rearrangement is below."]
      ], read: ["这两条菲涅耳分式是边界接续式的解，不是两条额外定律；r、t 仍是场幅度比而非能量百分数。", "These Fresnel fractions solve the two boundary conditions; they are not additional laws. r and t remain field-amplitude ratios, not energy percentages."] },
      { title: ["p 通道：规则没换，改变的是电场投影", "p channel: the rules stay; the electric projection changes"], before: ["现在把振动方向转到入射面内，仍使用同一组 E、H 切向连续。E 要投影才得到沿界面的分量，所以出现 cosθ；所选反射 p 正向使 E 的反射项变成减号，H 的方向给出 1+rₚ。不要把 s 通道的正负原样抄来。", "Rotate E into the incidence plane but retain tangential E/H matching. E must be projected onto the surface, producing cosθ; the chosen reflected p basis gives a minus sign in E, while H contains 1+rₚ. Do not copy the s signs."], eqLead: [
        ["先比较沿界面的电场：三束光的投影与各自角度一起出现。", "First compare surface-parallel E: each ray contributes its angle-dependent projection."],
        ["再比较沿界面的磁场：p 基底使反射项取加号。", "Then compare tangential H: the p-basis convention gives the reflected term a plus sign."],
        ["由第二式写出 tₚ=n₁(1+rₚ)/n₂，代回第一式并收集 rₚ。", "Write tₚ=n₁(1+rₚ)/n₂ from the second equation, insert it into the first, and collect rₚ."],
        ["把 rₚ 回代得到 tₚ；完整移项可在下方展开。", "Substitute rₚ back to obtain tₚ; expand the algebra below if needed."]
      ], read: ["两种偏振会分到不同场幅度，是几何投影与同一电磁规则共同作用的结果；下一步用正入射检查符号。", "The two polarizations get different field shares from geometry under the same electromagnetic rules. Next check the signs at normal incidence."] },
      { title: ["用正入射检查：系数正负要连同箭头读", "Normal-incidence check: read signs together with arrows"], before: ["把角度都取 0°，各余弦变 1，式子最简单。空气 1 到玻璃 1.5 给 rₛ=−0.2、rₚ=+0.2、t=0.8。看起来反射正负相反，是否同一表面却给矛盾结果？关键是两个通道比较场时用的正向箭头不同。", "At normal incidence all cosines are 1. Air 1 to glass 1.5 gives rₛ=−0.2, rₚ=+0.2 and t=0.8. Opposite reflection signs appear contradictory only if we forget the different reference arrows."], read: ["正入射极限里反射 p 正向与入射 p 正向相反，所以标量 +0.2 仍对应实验室固定轴上反向的场；s 的 −0.2 给出相同物理结论。两个通道的反射能量都占 4%，不是一个产生负功率。", "In the normal-incidence limit, reflected and incident p basis arrows oppose. Scalar +0.2 thus still gives a reversed field in a fixed laboratory axis, just as s's −0.2 does. Both channels reflect 4% of power; neither creates negative power."] }
    ],
    check: { question: ["为什么已知折射角后，还不能直接知道透射了多少能量？", "Why does a known refraction angle not yet tell us the transmitted energy?"], answer: ["方向只规定几何，还需边界条件求场幅度，之后再把场幅度换成法向功率，不能把 t 直接当能量比例。", "Geometry alone leaves amplitudes unknown. Boundary conditions determine fields; those must then be converted to normal power. t itself is not an energy fraction."] },
    next: ["带到 1.6.3：会计算场系数之后，改变角度，看曲线的负号、零点和传播边界各表示什么。", "Into §1.6.3: with coefficients defined, vary angle and interpret their signs, zeros and propagation limits."]
  },
  "1.6.3": {
    question: ["曲线过零、变负、走到边界，分别是哪件事？", "What do a zero, a negative value and a propagation limit mean?"],
    setup: ["上一节解出系数，这一节不再发明新公式，而把它当成可变化的函数来读。始终分开三类信息：方向基底下的正负、某通道没有反射、另一侧不再有实传播角。", "We now read the coefficients as variable functions rather than introduce unrelated formulas. Keep three ideas separate: basis-dependent sign, zero reflection in one channel, and the absence of a real transmitted propagation angle."],
    terms: [
      { name: ["负实系数", "Negative real coefficient"], meaning: ["相对于选定正向，相位多 π；不是把能量减成负数。“半波损失”是相位术语。", "A π phase shift relative to the selected basis, not negative energy. Half-wave loss is a phase expression."] },
      { name: ["布儒斯特角 θB", "Brewster angle θB"], meaning: ["p 通道反射场为零的入射角；s 通道通常仍反射。", "Incidence angle with zero p reflection; s usually still reflects."] },
      { name: ["临界角 θc", "Critical angle θc"], meaning: ["仅从高折射率入射到低折射率时，透射传播角达到 90° 的边界。", "For high-to-low index only, the boundary where the transmitted propagation angle reaches 90°."] }
    ],
    observe: ["先选低到高折射率，找到 p 系数穿过零的位置；再换高到低，找临界标记。它们不是同一个点。进入全反射区后，图不再假装系数仍是普通实数。", "First choose low-to-high index and locate the p zero. Then choose high-to-low and locate the critical boundary. They are different points. Beyond the latter, the figure does not pretend amplitudes remain real coefficients."],
    blocks: [
      { title: ["先读正负：它说明相位，不说明能量的符号", "Read sign first: it describes phase, not energy sign"], before: ["沿用上一节的基底，系数等于一个负实数，就是把相量反向转半圈，再缩放长度。用复数语言，这与多一个 π 相位相同。但 p 的基底本身也随光线方向变化，若要比较实验室中的两支箭头，还要把基底一起带回去。", "In the previous basis, a negative real coefficient reverses a phasor by half a turn and scales its length: an extra phase π. But p's basis also changes with ray direction. Comparing laboratory arrows therefore requires carrying the basis along with the scalar."], read: ["所以负号不是“有负的反射能量”，也不表示一半能量丢了。展开部分保留原公式便于复算；初读先在图上区分正负两边，再进入更有物理特征的零点。", "A minus sign is neither negative reflected energy nor loss of half the energy. The original formulas remain below for recalculation; first distinguish the two signs on the plot, then study its physically special zeros."], advanced: true },
      { title: ["分别追问两个特殊位置：哪个通道为零，哪条路不再传播", "Ask separately: which channel vanishes, and which route stops propagating?"], before: ["第一个问题：令上一节 rₚ 分子为零，再与 n₁sinθ₁=n₂sinθ₂ 同时满足，得到使 p 反射消失的 θB；两条光线此时互相垂直，整理为 tanθB=n₂/n₁。第二个问题：只在 n₁>n₂ 时，令折射角到 90°，斯涅耳定律变成 n₁sinθc=n₂。这是另一个边界，不是同一零点。", "First set the numerator of rₚ from the previous section to zero while keeping n₁sinθ₁=n₂sinθ₂. At θB the reflected p field vanishes and the rays are perpendicular, giving tanθB=n₂/n₁. Separately, only for n₁>n₂, let the transmitted angle reach 90°; Snell's law becomes n₁sinθc=n₂. That is a propagation limit, not the same zero."], read: ["读 tanθB=n₂/n₁ 为“使 p 反射消失的角度”；读 sinθc=n₂/n₁ 时必须附带 n₁>n₂。全反射区的反射幅值模为 1，但还有复相移，不是简单把 r 写成 +1；详细相移留在未制作的 1.7。", "tanθB=n₂/n₁ locates zero p reflection. sinθc=n₂/n₁ requires n₁>n₂ and locates a propagation boundary. In total reflection the coefficient magnitude is 1 but its phase is generally complex, not simply r=+1. Detailed phase is reserved for the not-yet-developed §1.7."] },
      { title: ["用两个入射方向，把两种角度彻底分开", "Use both incidence directions to distinguish the two angles"], before: ["现在给 n=1 与 1.5 做数值检验。空气到玻璃有 θB≈56.31°，却没有从这一侧产生的临界角；玻璃到空气则同时有 θB≈33.69° 与 θc≈41.81°。改变入射方向，问题的条件也改变，不能只记一个数。", "With indices 1 and 1.5, air-to-glass has θB≈56.31° but no critical angle from that side. Glass-to-air has θB≈33.69° and θc≈41.81°. Reversing incidence changes conditions, not just a number to memorize."], read: ["到这里会读场系数曲线了，但它仍不是功率曲线：负值、零点都需要先按场来解释。下一节把同一批 r、t 转成总能量账本，检查流入与流出是否守恒。", "We can now read field-coefficient plots, but these are not yet power plots. Interpret signs and zeros as fields first. Next turn the same r and t into an energy ledger and test conservation."] }
    ],
    check: { question: ["“p 没有反射”和“所有光都反射”为什么不能当成同一种现象？", "Why are zero p reflection and total reflection not the same phenomenon?"], answer: ["前者在布儒斯特角只去掉一个反射通道；后者在高到低超过临界角时没有透射的法向传播功率。条件和能量结果都不同。", "The first removes one reflected channel at Brewster incidence. The second, above the high-to-low critical angle, has no transmitted normal travelling-wave power. Conditions and energy outcomes differ."] },
    next: ["带到 1.6.4：将电场系数变成可测功率时，要把介质与斜入射面积投影一起算进去。", "Into §1.6.4: converting fields to measured power also requires material and oblique-area factors."]
  },
  "1.6.4": {
    question: ["透射场幅度是 0.8 倍，为什么透射功率不是 64%？", "If transmitted field is 0.8 times incident, why is transmitted power not 64%?"],
    setup: ["1.6.2 算的是电场，不是每秒穿过界面的能量。把 1.4.3 的场—光强关系接回来，再比较同一块界面的流入流出，就能算真正的反射率 R 与透射率 T。大写与小写有意区分。", "§1.6.2 calculated fields, not energy crossing the interface per second. Reuse §1.4.3's field–intensity relation, then compare incoming and outgoing power over the same surface patch. Uppercase R and T deliberately differ from lowercase r and t."],
    terms: [
      { name: ["R、T", "R, T"], meaning: ["反射、透射的法向功率分别除以入射功率，取正的比例；不是带正负的场比。", "Positive ratios of reflected or transmitted normal power to incident power, not signed field ratios."] },
      { name: ["I 与 P", "I and P"], meaning: ["I 按垂直光束的面积计；P 是穿过选定一整块界面的功率，所以斜入射时还需投影。", "I is per area perpendicular to a beam; P crosses an entire selected interface patch, requiring projection at oblique incidence."] },
      { name: ["cosθ 投影", "cosθ projection"], meaning: ["同样面积的表面，朝向光束不同，正面接住的面积也不同；余弦给出这个比例。", "A fixed surface patch presents different cross-sectional area to differently directed beams; cosine supplies that factor."] }
    ],
    observe: ["先设正入射、n₁=1、n₂=1.5，读 R=0.04、T=0.96；再斜入射，检查 s、p 各自的两块功率是否加起来为 1。图中现在显示的是能量，不是上一节的带符号系数。", "At normal incidence with n₁=1 and n₂=1.5, read R=0.04 and T=0.96. Then tilt incidence and check that reflected plus transmitted power sums to 1 in each channel. These are energy shares, not signed field coefficients."],
    blocks: [
      { title: ["先统一收能量的面积，才有公平的比值", "Compare power through the same area before taking ratios"], before: ["1.4.3 给 I=E₀²/(2Z)，其中 Z 是材料的波阻抗。要比较界面两侧，选同一小块面积 ΔA；它相对光束的正面面积是 ΔA cosθ，所以穿过功率为 I cosθ ΔA。ΔA 是面积，不是振幅 A。", "§1.4.3 gives I=E₀²/(2Z), with material impedance Z. Compare both sides using one patch ΔA. Its beam-facing area is ΔA cosθ, so crossing power is I cosθ ΔA. ΔA is area, not field amplitude A."], read: ["这就解释为什么单纯比较 E² 还不够：材料改变每单位场幅度的能流，倾角改变穿过表面的面积。下一步做比值，看看哪些因素能约掉，哪些不能。", "Squaring E alone misses two effects: material sets flux for a given amplitude, and tilt sets the effective crossing area. Next take ratios to see what cancels."] },
      { title: ["同侧反射能约掉的因素，跨介质透射不能约", "Reflection cancels factors that transmission must retain"], before: ["反射仍在介质 1，且反射角等于入射角，所以材料与余弦都相同，功率比只剩场比的模平方。透射却换了材料与角度：非磁性材料中 I 与 nE₀² 成正比，因此必须保留 n₂/n₁，再乘 cosθ₂/cosθ₁。", "Reflection remains in medium 1 at the same angle, so material and cosine factors cancel, leaving the squared field-ratio magnitude. Transmission changes both: nonmagnetic I is proportional to nE₀², requiring n₂/n₁ and cosθ₂/cosθ₁."], read: ["这才得到 R=|r|² 与带前因子的 T。| | 取模，避免把相位正负当功率正负。无吸收、无额外能量通道时，每个偏振都有 R+T=1，可以反过来检查计算有没有漏投影或漏折射率。", "This gives R=|r|² and T with its prefactor. Magnitude signs prevent phase signs from becoming power signs. With no absorption or extra energy channels, R+T=1 for each polarization, a check for missing projection or index factors."] },
      { title: ["自然光的两条正交通道，要先分别计能量", "For unpolarized light, count each orthogonal channel's energy first"], before: ["1.4.4 说理想自然光在两条横向正交轴的平均入射能量相等。因此先给 s、p 各分一半，再分别乘对应反射率，最后加功率。不是先把可能正负相反的 r 平均再平方。", "§1.4.4 assigns equal mean incident power to two orthogonal transverse channels for ideal unpolarized light. Give each half the input, multiply by its own reflectance, then add powers—not signed r values before squaring."], read: ["多表面时也先说明跟踪哪条光路：若只跟踪主透射束，每过一面就再乘一个透射率。12 个近正入射、n=1.52 的无吸收界面给约 0.593，但没有把来回反射后再出来的光都计入，不能冒充完整薄膜计算。", "For multiple surfaces, specify the path tracked. Following only the primary transmitted beam multiplies successive transmittances: twelve near-normal n=1.52 lossless interfaces give about 0.593. Returned multiply reflected light is omitted; this is not a complete thin-film calculation."] },
      { title: ["回到 0.8 的例子，把能量账本算闭合", "Return to 0.8 and close the energy ledger"], before: ["正入射从 1 到 1.5，场系数的模为 0.2 和 0.8。反射功率比例是 0.2²=0.04；透射必须是 1.5×0.8²=0.96，不能漏掉更换材料的系数。", "At normal incidence from 1 to 1.5, field magnitudes are 0.2 and 0.8. Reflection is 0.2²=0.04. Transmission is 1.5×0.8²=0.96; the material factor cannot be dropped."], read: ["若入射 10 W，就得到反射 0.4 W、透射 9.6 W，合计 10 W。现在场系数与功率比终于接上了；下一节用 s、p 分走能量不同，解释反光为何会偏向某种振动方向。", "For 10 W input, reflected power is 0.4 W and transmitted power 9.6 W, totaling 10 W. Field coefficients and power ratios now connect. Next their unequal s/p shares explain polarization by reflection."] }
    ],
    check: { question: ["为什么计算 T 时乘 n₂/n₁，却不对 R 这样乘？", "Why does T contain n₂/n₁ while R does not?"], answer: ["反射和入射在同一材料，材料系数约掉；透射在另一材料，单位场平方对应的能流不同，所以保留两侧之比。斜入射还要保留余弦比。", "Reflection and incidence share one medium, so its factor cancels. Transmission changes the energy flux per squared field amplitude, leaving a material ratio and, at oblique incidence, a cosine ratio."] },
    next: ["带到 1.6.5：两通道的功率反射率通常不等；若一条通道恰好不反射，返回来的光还剩什么方向？", "Into §1.6.5: the channels usually reflect unequal powers. If one reflects none, what oscillation direction remains?"]
  },
  "1.6.5": {
    question: ["没有偏振片，为什么玻璃反光也会偏振？", "Why can a reflection polarize light without a polarizer?"],
    setup: ["把前面三条线接在一起：自然光含平均等能量的 s、p，菲涅耳公式让它们反射比例不同，布儒斯特角又让 p 反射为零。因此界面本身就能筛选方向。本节分开问“剩下的光偏向哪边”和“还剩多少能量”。", "Connect three ideas: unpolarized input has equal mean s/p powers, Fresnel coefficients reflect them unequally, and Brewster incidence removes p reflection. An interface therefore selects direction. Separate which direction remains from how much energy remains."],
    terms: [
      { name: ["线偏振", "Linear polarization"], meaning: ["电场沿固定横向轴来回振动；方向轴不等于光线传播轴。", "E oscillates along a fixed transverse axis, not along the ray's propagation axis."] },
      { name: ["偏振度 Dᵣ", "Polarization degree Dᵣ"], meaning: ["这里用反射 s、p 强度差相对总强度衡量方向偏好；1 表示只剩一个通道，不表示全部入射光反回。", "Here the reflected s/p intensity imbalance divided by their sum. One means a single channel remains, not all incident power is reflected."] },
      { name: ["α", "α"], meaning: ["线偏振入射场从 p 轴转向 s 轴的角度，决定两通道输入比例；不同于光线的入射角 θ₁。", "Angle of incident linear polarization measured from p toward s, setting their input weights; not ray incidence angle θ₁."] }
    ],
    observe: ["将入射角调到布儒斯特角附近，看 p 反射通道消失而 s 仍有输出，再看总反射功率并没有变成 100%。方向纯度与能量多少要分别读。", "Set incidence near Brewster and watch p reflection disappear while s remains. Total reflected power does not become 100%. Read directional purity separately from energy share."],
    blocks: [
      { title: ["先筛方向：p 消失后，反射光只剩 s", "First select direction: with p absent, reflected light is s"], before: ["上一节已会分别记 s、p 的能量。现在取含两通道的自然光：若角度让 Rp=0，反射光里就没有 p，只剩电场垂直入射面的 s，因而是线偏振。这与偏振片的方向筛选有相似结果，但这里靠的是界面的反射差异。", "We can already count s/p powers separately. For unpolarized input at Rp=0, reflected light contains no p and only s, perpendicular to the incidence plane: linear polarization. Directional selection resembles a polarizer's outcome, but arises from differential interface reflection."], read: ["这个特殊角正是 θB，不是全反射角。若输入原本只有 p，则此时根本没有反射光，不能给零光束指定偏振方向。下面回到两条已有规律，解释怎样找到这个角。", "That angle is θB, not a total-reflection angle. With purely p input, there is no reflected beam here, so no reflected polarization direction to assign. Next combine two earlier rules to locate θB."] },
      { title: ["用 p 零反射条件接上折射定律，找到角度", "Combine zero p reflection with refraction to find the angle"], before: ["rₚ 的分子为零时有 n₂cosθB=n₁cosθ₂；同时方向还须满足斯涅耳定律。对不同折射率的正常界面，两式一起给 θB+θ₂=90°。这解释了为何图中的反射、折射光线此时互相垂直。", "Zero numerator of rₚ gives n₂cosθB=n₁cosθ₂, while directions still obey Snell's law. For a nondegenerate unequal-index interface, together they give θB+θ₂=90°. This explains perpendicular reflected and refracted rays in the figure."], read: ["把 θ₂=90°−θB 放回折射定律，sinθ₂ 变 cosθB，约去后就是 tanθB=n₂/n₁。空气到 1.5 玻璃得 56.31°。1.4.2 的偶极轴向辐射零点提供直观联系，但定量计算仍依靠这里的边界条件。", "Substitute θ₂=90°−θB into Snell's law: sinθ₂ becomes cosθB, giving tanθB=n₂/n₁. Air to index 1.5 gives 56.31°. The dipole axial null in §1.4.2 offers intuition, while boundary conditions supply the quantitative result."] },
      { title: ["再算能量：100% 偏振，不等于 100% 反射", "Now count energy: fully polarized does not mean fully reflected"], before: ["在刚才的角度，空气到玻璃给 Rs≈0.14793、Rp=0。自然光把一半能量送到 s 通道，其中约 14.793% 反射，所以总反射约 7.40%。若要量化返回光偏向哪条轴，定义偏振度 Dᵣ 为两通道反射率之差的绝对值除以两者之和；两者都为零时没有反射光，不能定义它。这里只有 s 返回，所以方向纯度是 100%。", "At that angle, air to glass gives Rs≈0.14793 and Rp=0. Unpolarized input sends half its power into s, of which about 14.793% reflects: roughly 7.40% total. Define reflected polarization degree Dᵣ as the absolute difference of the two channel reflectances divided by their sum. If both vanish, there is no reflected beam and Dᵣ is undefined. Only s returns here, giving 100% directional purity."], read: ["Dᵣ 测方向偏好而非返回功率。若输入是线偏振 α，先用 sin²α、cos²α 分配通道，不能再套自然光各一半。这里的透射仍有两通道，因此并非同时全偏振。", "Dᵣ measures directional preference rather than total returned power. Linear input at α uses sin²α and cos²α weights, not the unpolarized half-and-half rule. Transmitted light still has both channels and is not fully polarized here."] },
      { title: ["若两通道都还在，反射也能转动偏振方向", "When both channels remain, reflection can rotate polarization"], before: ["不在布儒斯特角时，线偏振也可拆成 s、p 两分量。界面给它们乘不同 r，重新合成的箭头通常不再沿原方向。在本节实系数条件下，两分量仍只差 0 或 π 的相位，所以合成仍沿一条直线振动。", "Away from Brewster, resolve a linearly polarized field into s and p. Multiplication by different r values generally changes the recombined direction. Under the real-coefficient conditions here, relative phases remain 0 or π, so the resulting oscillation is still linear."], read: ["例如 θ₁=50°、α=45° 时，反射基底中的方向角约 −80.29°。必须保留系数正负并说明使用哪个基底；只比较两条正的幅度长度会丢方向信息。全反射的复相移可能带来椭圆偏振，但那属于下一批，不混进当前实系数结论。", "For θ₁=50° and α=45°, the reflected-basis angle is about −80.29°. Retain coefficient signs and specify the basis; comparing only positive lengths loses direction. Complex phases in total reflection can produce elliptical polarization, but that is outside the present real-coefficient result."] }
    ],
    check: { question: ["反射光只占 7.40% 却完全偏振，这矛盾吗？", "Can reflection be only 7.40% of the input yet be fully polarized?"], answer: ["不矛盾。7.40% 比较返回与入射的能量；完全偏振只说返回这部分光的振动方向有固定轴，不说它有多少。", "Yes. 7.40% compares reflected to input energy. Fully polarized describes the fixed oscillation axis of the returning portion, not how much energy it carries."] },
    next: ["本批到这里形成闭环：源与波形 → 幅度和能量 → 界面接续 → 方向 → 场系数 → 功率 → 偏振。教材下一节 1.7 将讨论全反射相移，尚未在本课程展开。", "This batch closes the chain: sources and waves → amplitude and energy → interface matching → directions → field coefficients → power → polarization. The book's next §1.7 develops total-reflection phase; it is not yet included here."]
  }
};

// Introduce each result where its reasoning is complete: spherical envelope,
// then the separate s/p matching equations for the Fresnel coefficients.
// Both registered languages keep the same equations, links and block alignment.
for (const chapters of [window.OpticsCourseChapters, window.OpticsCourseChaptersEn]) {
  const sphere = chapters.flatMap(chapter => chapter.lessons).find(lesson => lesson.code === "1.3.1");
  const waveFunction = sphere.blocks[0].eq;
  delete sphere.blocks[0].eq;
  sphere.blocks[1].eq.push(...waveFunction);
  const fresnel = chapters.flatMap(chapter => chapter.lessons).find(lesson => lesson.code === "1.6.2");
  const [rs, rp] = fresnel.blocks[0].eq;
  delete fresnel.blocks[0].eq;
  fresnel.blocks[1].eq.splice(2, 0, rs);
  fresnel.blocks[2].eq.splice(2, 0, rp);
}
